const expandedWorkflowGroupsStorageKey = 'km-editor.workflow-groups.user-expanded.v2';
const editorLayoutStorageKey = 'km-editor.editor-layout.v1';
const constrainedSidebarMediaQuery = '(max-width: 1280px), (max-height: 720px)';

type EditorLayoutPreference = 'classic' | 'focused';

function readEditorLayoutPreference(): EditorLayoutPreference {
  if (typeof window === 'undefined') {
    return 'classic';
  }

  try {
    return window.localStorage.getItem(editorLayoutStorageKey) === 'focused'
      ? 'focused'
      : 'classic';
  } catch {
    return 'classic';
  }
}

function writeEditorLayoutPreference(layout: EditorLayoutPreference) {
  if (typeof window === 'undefined') {
    return;
  }

  try {
    window.localStorage.setItem(editorLayoutStorageKey, layout);
  } catch {
    // The in-memory preference still applies when localStorage is unavailable.
  }
}

function readSidebarCompactPreference() {
  if (typeof window === 'undefined') {
    return false;
  }

  try {
    return window.localStorage.getItem(sidebarCompactStorageKey) === 'true';
  } catch {
    return false;
  }
}

function writeSidebarCompactPreference(isCompact: boolean) {
  if (typeof window === 'undefined') {
    return;
  }

  try {
    window.localStorage.setItem(sidebarCompactStorageKey, String(isCompact));
  } catch {
    // The in-memory preference still applies when localStorage is unavailable.
  }
}

function useMediaQuery(query: string) {
  const getMatches = () =>
    typeof window !== 'undefined' && typeof window.matchMedia === 'function'
      ? window.matchMedia(query).matches
      : false;
  const [matches, setMatches] = useState(getMatches);

  useEffect(() => {
    if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') {
      return;
    }

    const mediaQuery = window.matchMedia(query);
    const handleChange = () => setMatches(mediaQuery.matches);
    handleChange();
    mediaQuery.addEventListener('change', handleChange);

    return () => mediaQuery.removeEventListener('change', handleChange);
  }, [query]);

  return matches;
}

function keepSidebarItemVerticallyVisible(
  scrollRegion: HTMLDivElement,
  activeNavigationItem: HTMLElement
) {
  const scrollRegionBounds = scrollRegion.getBoundingClientRect();
  const activeItemBounds = activeNavigationItem.getBoundingClientRect();

  if (activeItemBounds.top < scrollRegionBounds.top) {
    scrollRegion.scrollTop += activeItemBounds.top - scrollRegionBounds.top;
  } else if (activeItemBounds.bottom > scrollRegionBounds.bottom) {
    scrollRegion.scrollTop += activeItemBounds.bottom - scrollRegionBounds.bottom;
  }
}

function readExpandedWorkflowGroups(game: ProjectGame | null) {
  if (!game || typeof window === 'undefined') {
    return new Set<WorkflowNavigationGroup['id']>();
  }

  try {
    const storedValue = window.localStorage.getItem(
      `${expandedWorkflowGroupsStorageKey}.${game}`
    );
    if (!storedValue) {
      return new Set<WorkflowNavigationGroup['id']>();
    }

    const parsedValue = JSON.parse(storedValue) as unknown;
    if (!Array.isArray(parsedValue)) {
      return new Set<WorkflowNavigationGroup['id']>();
    }

    const knownGroupIds = new Set(workflowNavigationGroups.map((group) => group.id));
    return new Set(
      parsedValue.filter(
        (groupId): groupId is WorkflowNavigationGroup['id'] =>
          typeof groupId === 'string' &&
          knownGroupIds.has(groupId as WorkflowNavigationGroup['id'])
      )
    );
  } catch {
    return new Set<WorkflowNavigationGroup['id']>();
  }
}

function writeExpandedWorkflowGroups(
  game: ProjectGame | null,
  groups: ReadonlySet<WorkflowNavigationGroup['id']>
) {
  if (!game || typeof window === 'undefined') {
    return;
  }

  try {
    window.localStorage.setItem(
      `${expandedWorkflowGroupsStorageKey}.${game}`,
      JSON.stringify([...groups])
    );
  } catch {
    // The in-memory expansion state still applies when localStorage is unavailable.
  }
}

