  const handleValidateDynamaxAdventureEditSession = async () => {
    if (!editSession || pendingEditSessionMutationTokensRef.current.size > 0) {
      return;
    }

    const runId = editSessionOperationRunRef.current + 1;
    editSessionOperationRunRef.current = runId;
    const initialSessionSignature = getEditSessionSignature(editSession);
    const isCurrentOperation = () =>
      editSessionOperationRunRef.current === runId &&
      getEditSessionSignature(editSessionRef.current) === initialSessionSignature;

    setIsSessionValidating(true);
    setIsChangePlanCreating(true);
    setBridgeDiagnostics([]);
    setEditValidationDiagnostics([]);
    setDynamaxAdventurePanelDiagnostics([]);
    setDynamaxAdventureChangePlan(null);
    setDynamaxAdventureChangePlanSessionSignature(null);
    setDynamaxAdventureApplyResult(null);
    setChangePlan(null);
    setApplyResult(null);
    setValidatedEditSessionSignature(null);
    setChangePlanSessionSignature(null);

    try {
      const response = await bridge.validateEditSession({
        paths: createProjectPaths(draftPaths),
        session: editSession
      });
      if (!isCurrentOperation()) {
        return;
      }
      const nextSessionSignature = getEditSessionSignature(response.session);

      if (!response.isValid || nextSessionSignature === null) {
        setDynamaxAdventurePanelDiagnostics(response.diagnostics);
        return;
      }

      const planResponse = await bridge.createChangePlan({
        outputMode: response.session.authoringBinding?.outputMode ?? undefined,
        paths: createProjectPaths(draftPaths),
        session: response.session
      });
      if (!isCurrentOperation()) {
        return;
      }
      editSessionRef.current = response.session;
      setEditSession(response.session);
      setEditSessionSection(
        response.session.pendingEdits.length > 0 ? 'dynamaxAdventures' : null
      );
      setDynamaxAdventurePanelDiagnostics(response.diagnostics);
      setDynamaxAdventureChangePlan(planResponse.changePlan);
      setDynamaxAdventureChangePlanSessionSignature(nextSessionSignature);
    } catch (error) {
      if (!isCurrentOperation()) {
        return;
      }
      setBridgeDiagnostics(toBridgeDiagnostics(error));
    } finally {
      if (editSessionOperationRunRef.current === runId) {
        setIsSessionValidating(false);
        setIsChangePlanCreating(false);
      }
    }
  };

  const handleApplyDynamaxAdventureChangePlan = async () => {
    if (!outputSafety.canApply) {
      return;
    }
    if (!editSession || !visibleDynamaxAdventureChangePlan) {
      return;
    }

    const runId = editSessionOperationRunRef.current + 1;
    editSessionOperationRunRef.current = runId;
    const reviewedSession = editSession;
    const reviewedPlan = visibleDynamaxAdventureChangePlan;
    const reviewedSessionSignature = getEditSessionSignature(reviewedSession);
    const reviewedPlanFingerprint = calculatePendingPayloadSha256(
      JSON.stringify(reviewedPlan)
    );
    const paths = createProjectPaths(draftPathsRef.current);
    const pathsSignature = JSON.stringify(paths);
    const projectScopeGeneration = projectScopeGenerationRef.current;
    const isCurrentProjectOperation = () =>
      editSessionOperationRunRef.current === runId &&
      projectScopeGenerationRef.current === projectScopeGeneration &&
      JSON.stringify(createProjectPaths(draftPathsRef.current)) === pathsSignature;
    const isCurrentReviewedOperation = () => {
      const currentPlan = visibleDynamaxAdventureChangePlanRef.current;
      return (
        isCurrentProjectOperation() &&
        getEditSessionSignature(editSessionRef.current) === reviewedSessionSignature &&
        currentPlan !== null &&
        calculatePendingPayloadSha256(JSON.stringify(currentPlan)) ===
          reviewedPlanFingerprint
      );
    };

    setIsChangePlanApplying(true);
    setBridgeDiagnostics([]);
    setEditValidationDiagnostics([]);
    setDynamaxAdventurePanelDiagnostics([]);
    setDynamaxAdventureApplyResult(null);
    setApplyResult(null);
    setWorkProgress(createIndeterminateWorkProgress(
      'Applying Dynamax Adventure Changes',
      'Writing reviewed adventure changes',
      applyProgressSteps,
      1
    ));

    try {
      const response = await bridge.applyChangePlan({
        changePlan: reviewedPlan,
        outputMode: reviewedSession.authoringBinding?.outputMode ?? undefined,
        paths,
        session: reviewedSession
      });
      if (!isCurrentReviewedOperation()) {
        return;
      }
      const hasApplyErrors = response.applyResult.diagnostics.some(
        (diagnostic) => diagnostic.severity === 'error'
      );
      const completedApplyResult = completeSuccessfulApplyResult(
        response.applyResult,
        reviewedPlan
      );

      if (!hasApplyErrors) {
        const wasBoundChangeSetSession = reviewedSession.authoringBinding !== null;
        editSessionMutationGenerationRef.current += 1;
        editSessionMutationQueueRef.current = Promise.resolve();
        editSessionRef.current = null;
        setEditSession(null);
        setEditSessionSection(null);
        setDynamaxAdventureChangePlan(null);
        setDynamaxAdventureChangePlanSessionSignature(null);
        setDynamaxAdventurePanelDiagnostics([]);
        setChangePlan(null);
        setApplyResult(null);
        setValidatedEditSessionSignature(null);
        setChangePlanSessionSignature(null);
        if (userFacingFeatureVisibility.namedChangeSets && wasBoundChangeSetSession) {
          suppressNextChangeSetWorkflowInvalidationRef.current = true;
          try {
            await changeSetWorkspace.refresh(null);
          } catch (error) {
            setBridgeDiagnostics(toBridgeDiagnostics(error));
          } finally {
            suppressNextChangeSetWorkflowInvalidationRef.current = false;
          }
        }
      }

      setDynamaxAdventureApplyResult(completedApplyResult);

      if (!hasApplyErrors && response.applyResult.writtenFiles.length > 0) {
        setWorkProgress(createIndeterminateWorkProgress(
          'Applying Dynamax Adventure Changes',
          'Refreshing loaded editor data',
          applyProgressSteps,
          2
        ));
        try {
          await refreshLoadedWorkflowsAfterApply(paths, isCurrentProjectOperation);
        } catch (error) {
          if (isCurrentProjectOperation()) {
            setDynamaxAdventureApplyResult(completedApplyResult);
            setBridgeDiagnostics(toBridgeDiagnostics(error));
          }
        }
      }
      if (
        completedApplyResult.outputTransaction !== null ||
        completedApplyResult.writtenFiles.length > 0
      ) {
        await notifySemanticOutputMutation();
      }
    } catch (error) {
      if (!isCurrentReviewedOperation()) {
        return;
      }
      setBridgeDiagnostics(toBridgeDiagnostics(error));
      await notifySemanticOutputFailure(error);
    } finally {
      if (editSessionOperationRunRef.current === runId) {
        setIsChangePlanApplying(false);
        setWorkProgress(null);
      }
    }
  };

  const handleCancelDynamaxAdventurePreview = useCallback(() => {
    dynamaxAdventurePreviewRunRef.current += 1;
  }, []);

  const handleUpdateShopChanges = async (
    shopId: string,
    inventoryChanges: ShopInventoryDraftChange[],
    priceChanges: ShopItemPriceChange[],
    rowFieldChanges: ShopInventoryDraftChange[] = []
  ) => {
    if (
      inventoryChanges.length === 0 &&
      priceChanges.length === 0 &&
      rowFieldChanges.length === 0
    ) {
      return false;
    }

    setIsShopUpdating(true);
    if (priceChanges.length > 0) {
      setIsItemUpdating(true);
    }
    setBridgeDiagnostics([]);
    setEditValidationDiagnostics([]);

    try {
      const response = await runEditSessionMutation(
        async (session) => {
          const originalSession = session;
          const originalShopsWorkflow = shopsWorkflow;
          const originalItemsWorkflow = itemsWorkflow;
          let nextSession = session;
          let nextShopsWorkflow = shopsWorkflow;
          let nextItemsWorkflow = itemsWorkflow;
          const nextDiagnostics: ApiDiagnostic[] = [];
          let didSucceed = true;

          for (const change of inventoryChanges) {
            const updateResponse = await bridge.updateShopInventoryItem({
              field: change.field,
              paths: createProjectPaths(draftPaths),
              rowId: change.rowId,
              session: nextSession,
              shopId,
              slot: change.slot,
              value: change.value
            });
            nextDiagnostics.push(...updateResponse.diagnostics);
            if (updateResponse.diagnostics.some((diagnostic) => diagnostic.severity === 'error')) {
              didSucceed = false;
              break;
            }
            nextSession = updateResponse.session;
            nextShopsWorkflow = updateResponse.workflow;
          }

          if (didSucceed) {
            for (const change of rowFieldChanges) {
              const updateResponse = await bridge.updateShopInventoryItem({
                field: change.field,
                paths: createProjectPaths(draftPaths),
                rowId: change.rowId,
                session: nextSession,
                shopId,
                slot: change.slot,
                value: change.value
              });
              nextDiagnostics.push(...updateResponse.diagnostics);
              if (
                updateResponse.diagnostics.some(
                  (diagnostic) => diagnostic.severity === 'error'
                )
              ) {
                didSucceed = false;
                break;
              }
              nextSession = updateResponse.session;
              nextShopsWorkflow = updateResponse.workflow;
            }
          }

          if (didSucceed && priceChanges.length > 0) {
            const updateResponse = await bridge.updateItemFields({
              paths: createProjectPaths(draftPaths),
              session: nextSession,
              updates: priceChanges.map((change) => ({
                field: change.field,
                itemId: change.itemId,
                value: change.value
              }))
            });
            nextDiagnostics.push(...updateResponse.diagnostics);
            if (updateResponse.diagnostics.some((diagnostic) => diagnostic.severity === 'error')) {
              didSucceed = false;
            } else {
              nextSession = updateResponse.session;
              nextItemsWorkflow = updateResponse.workflow;
            }
          }

          return {
            diagnostics: nextDiagnostics,
            didSucceed,
            itemsWorkflow: didSucceed ? nextItemsWorkflow : originalItemsWorkflow,
            session: didSucceed ? nextSession! : (originalSession ?? nextSession!),
            shopsWorkflow: didSucceed ? nextShopsWorkflow : originalShopsWorkflow
          };
        },
        (updateResponse) => {
          if (updateResponse.didSucceed && updateResponse.itemsWorkflow) {
            setItemsWorkflow(updateResponse.itemsWorkflow);
          }
          if (updateResponse.didSucceed && updateResponse.shopsWorkflow) {
            setShopsWorkflow(
              overlayShopWorkflowItemPrices(updateResponse.shopsWorkflow, priceChanges)
            );
          }
          setEditValidationDiagnostics(updateResponse.diagnostics);
        },
        getEditSessionForSection('shops')
      );
      return response?.didSucceed === true;
    } catch (error) {
      setBridgeDiagnostics(toBridgeDiagnostics(error));
      return false;
    } finally {
      setIsShopUpdating(false);
      if (priceChanges.length > 0) {
        setIsItemUpdating(false);
      }
    }
  };

