function TextSection({
  editSession,
  isEditStarting,
  isPagedResultWindow,
  isTextLoading,
  isTextQueryPending,
  isTextUpdating,
  onCategoryChange,
  onLanguageChange,
  onPageChange,
  onSearchChange,
  onSelectTextEntry,
  onStartEditSession,
  onUpdateTextEntry,
  searchText,
  selectedCategoryId,
  selectedLanguage,
  selectedTextKey,
  workflow
}: {
  editSession: EditSession | null;
  isEditStarting: boolean;
  isPagedResultWindow: boolean;
  isTextLoading: boolean;
  isTextQueryPending: boolean;
  isTextUpdating: boolean;
  onCategoryChange: (categoryId: string) => void;
  onLanguageChange: (language: string) => void;
  onPageChange: (offset: number) => void;
  onSearchChange: (searchText: string) => void;
  onSelectTextEntry: (textKey: string | null) => void;
  onStartEditSession: () => void;
  onUpdateTextEntry: (textKey: string, value: string) => Promise<boolean>;
  searchText: string;
  selectedCategoryId: string | null;
  selectedLanguage: string | null;
  selectedTextKey: string | null;
  workflow: TextWorkflow | null;
}) {
  const { t, translateLiteral } = useLocalization();
  const entries = useMemo(
    () => overlayPendingTextValues(workflow?.entries ?? [], editSession),
    [editSession, workflow?.entries]
  );
  const filteredEntries = useMemo(
    () => (workflow?.page ? entries : filterTextEntries(entries, searchText)),
    [entries, searchText, workflow?.page]
  );
  const selectedEntry = useMemo(
    () =>
      filteredEntries.find((entry) => entry.textKey === selectedTextKey) ??
      filteredEntries[0] ??
      null,
    [filteredEntries, selectedTextKey]
  );
  const canEditText = workflow?.summary.availability === 'available';
  const pendingTextKeys = useMemo(() => getPendingTextKeys(editSession), [editSession]);
  const categories = workflow?.categories ?? [];
  const page = workflow?.page ?? null;
  const activeCategoryId = workflow?.selectedCategoryId ?? selectedCategoryId ?? 'all';
  const activeCategory = categories.find(
    (category) => category.categoryId === activeCategoryId
  );
  const activeCategoryLocalization = activeCategory
    ? textCategoryLocalizationKeys[activeCategory.categoryId]
    : undefined;
  const activeCategoryLabel = activeCategory
    ? activeCategoryLocalization
      ? t(activeCategoryLocalization.label)
      : translateLiteral(activeCategory.label)
    : t('text.categories.ariaLabel');
  const activeCategoryDescription = activeCategory
    ? activeCategoryLocalization
      ? t(activeCategoryLocalization.description)
      : translateLiteral(activeCategory.description)
    : '';
  const activeLanguage = workflow?.selectedLanguage ?? selectedLanguage ?? '';
  const resultStart = page && page.returnedEntryCount > 0 ? page.offset + 1 : 0;
  const resultEnd = page ? page.offset + page.returnedEntryCount : filteredEntries.length;
  const pageNumber = page ? Math.floor(page.offset / page.limit) + 1 : 1;

  return (
    <>
      <section aria-labelledby="text-heading" className="panel wide-panel">
        <div className="panel-heading">
          <ListChecks aria-hidden="true" size={18} />
          <h2 id="text-heading">Text and Dialogue Map</h2>
        </div>

        <div className="items-toolbar text-toolbar">
          {workflow && workflow.languages.length > 0 ? (
            <div className="path-field text-language-field">
              <FieldLabel
                help={t('text.language.help')}
                htmlFor="text-game-language"
                label={t('text.language.label')}
              />
              <select
                aria-label={t('text.language.ariaLabel')}
                className="km-select-control"
                data-localization-ignore="true"
                disabled={isTextLoading || isTextUpdating}
                id="text-game-language"
                onChange={(event) => onLanguageChange(event.target.value)}
                value={activeLanguage}
              >
                {workflow.languages.map((language) => (
                  <option key={language.language} value={language.language}>
                    {language.label}
                  </option>
                ))}
              </select>
            </div>
          ) : null}
          <label className="search-box items-search">
            <Search aria-hidden="true" size={18} />
            <input
              aria-label={t('text.search.ariaLabel')}
              disabled={!workflow || isTextLoading || isTextUpdating}
              onChange={(event) => onSearchChange(event.target.value)}
              placeholder={t('text.search.placeholder')}
              type="search"
              value={searchText}
            />
          </label>
          <Metric
            label={
              page
                ? t('text.metrics.pageEntries')
                : isPagedResultWindow
                  ? 'Loaded results'
                  : 'Loaded entries'
            }
            value={
              workflow
                ? (page?.returnedEntryCount ?? workflow.stats.totalTextEntryCount).toString()
                : '0'
            }
          />
          <Metric
            label={categories.length > 0 ? t('text.metrics.availableFiles') : 'Source files'}
            value={workflow ? workflow.stats.sourceFileCount.toString() : '0'}
          />
          <Metric
            label="Pending changes"
            value={(editSession?.pendingEdits.length ?? 0).toString()}
          />
        </div>

        {workflow && categories.length > 0 ? (
          <nav aria-label={t('text.categories.ariaLabel')} className="text-category-browser">
            <div className="text-category-tabs">
              {categories.map((category) => {
                const localizationKeys = textCategoryLocalizationKeys[category.categoryId];

                return (
                  <button
                    aria-pressed={category.categoryId === activeCategoryId}
                    className={category.categoryId === activeCategoryId ? 'is-active' : ''}
                    disabled={isTextLoading || isTextUpdating}
                    key={category.categoryId}
                    onClick={() => onCategoryChange(category.categoryId)}
                    type="button"
                  >
                    <span>
                      {localizationKeys
                        ? t(localizationKeys.label)
                        : translateLiteral(category.label)}
                    </span>
                    <small>
                      {t('text.categories.fileCount', {
                        count: category.sourceFileCount
                      })}
                    </small>
                  </button>
                );
              })}
            </div>
            {activeCategory ? (
              <div className="editable-field-label-row text-category-context-help">
                <strong>{activeCategoryLabel}</strong>
                <ContextHelp label={activeCategoryLabel}>
                  {`${t('text.categories.help')} ${activeCategoryDescription}`}
                </ContextHelp>
              </div>
            ) : null}
          </nav>
        ) : null}

        {workflow && page ? (
          <nav aria-label={t('text.pagination.ariaLabel')} className="text-page-bar">
            <span aria-live="polite">
              {page.returnedEntryCount > 0
                ? t('text.pagination.showing', {
                    start: resultStart,
                    end: resultEnd,
                    page: pageNumber
                  })
                : t('text.pagination.empty', { page: pageNumber })}
              {page.hasNext ? ` · ${t('text.pagination.more')}` : ''}
            </span>
            <div>
              <button
                className="secondary-button"
                disabled={!page.hasPrevious || isTextLoading || isTextUpdating}
                onClick={() => onPageChange(Math.max(0, page.offset - page.limit))}
                type="button"
              >
                {t('text.pagination.previous')}
              </button>
              <button
                className="secondary-button"
                disabled={!page.hasNext || isTextLoading || isTextUpdating}
                onClick={() => onPageChange(page.offset + page.limit)}
                type="button"
              >
                {t('text.pagination.next')}
              </button>
            </div>
          </nav>
        ) : null}

        {workflow ? (
          <EditorSessionBar
            canEdit={
              canEditText && !isTextQueryPending && selectedEntry?.canEdit === true
            }
            isEditing={editSession !== null}
            isStarting={isEditStarting}
            label="Text"
            onStart={onStartEditSession}
            readOnlyReason={selectedEntry?.editBlockedReason}
          />
        ) : null}

        {workflow ? (
          <div className="text-layout">
            <div
              aria-busy={isTextLoading || undefined}
              aria-colcount={5}
              aria-label={t('text.table.ariaLabel')}
              aria-rowcount={filteredEntries.length + 1}
              className="text-table"
              role="table"
            >
              <div className="text-row text-row-heading" role="row">
                <span role="columnheader">{t('text.messageKey')}</span>
                <span role="columnheader">File</span>
                <span role="columnheader">Line</span>
                <span role="columnheader">Value</span>
                <span role="columnheader">Source</span>
              </div>
              <VirtualTableBody
                getKey={(entry) => entry.textKey}
                items={filteredEntries}
                resetKey={`${activeLanguage}:${activeCategoryId}:${page?.offset ?? 0}:${searchText}`}
                renderRow={(entry) => (
                  <button
                    aria-selected={selectedEntry?.textKey === entry.textKey}
                    className={`text-row ${selectedEntry?.textKey === entry.textKey ? 'text-row-selected' : ''} ${
                      pendingTextKeys.has(entry.textKey) ? 'text-row-pending' : ''
                    }`}
                    onClick={() => onSelectTextEntry(entry.textKey)}
                    role="row"
                    type="button"
                  >
                    <span data-localization-ignore="true" role="cell">
                      {entry.messageKey ?? entry.label}
                    </span>
                    <span data-localization-ignore="true" role="cell">
                      {entry.sourceFile}
                    </span>
                    <span role="cell">{entry.lineIndex}</span>
                    <span
                      aria-label={canonicalTextToEditorText(entry.value)}
                      className="text-value-summary"
                      data-localization-ignore="true"
                      role="cell"
                    >
                      {formatCanonicalTextSummary(entry.value)}
                    </span>
                    <span role="cell">{formatSourceLayer(entry.provenance.sourceLayer)}</span>
                  </button>
                )}
              />
            </div>

            <SelectedTextPanel
              canEditText={canEditText}
              editSession={editSession}
              editableFields={workflow.editableFields}
              entry={selectedEntry}
              isTextQueryPending={isTextQueryPending}
              isTextUpdating={isTextUpdating}
              onUpdateTextEntry={onUpdateTextEntry}
            />
          </div>
        ) : (
          <p className="empty-copy">Open Text from Editors to load backend message tables.</p>
        )}
      </section>

      <DiagnosticsSection diagnostics={workflow?.diagnostics ?? []} />
    </>
  );
}

function SelectedTextPanel({
  canEditText,
  editSession,
  editableFields,
  entry,
  isTextQueryPending,
  isTextUpdating,
  onUpdateTextEntry
}: {
  canEditText: boolean;
  editSession: EditSession | null;
  editableFields: TextEditableField[];
  entry: TextEntryRecord | null;
  isTextQueryPending: boolean;
  isTextUpdating: boolean;
  onUpdateTextEntry: (textKey: string, value: string) => Promise<boolean>;
}) {
  const { t } = useLocalization();
  const [draftsByTextKey, setDraftsByTextKey] = useState<Record<string, string>>({});
  const cancelActiveEditSession = useCancelActiveEditSession();
  const textValueTextareaRef = useRef<HTMLTextAreaElement | null>(null);
  const textValueSelectionRef = useRef({
    end: 0,
    start: 0,
    textKey: null as string | null
  });
  const valueField = editableFields.find((field) => field.field === 'value');
  const draftValue = entry ? draftsByTextKey[entry.textKey] ?? entry.value : '';
  const displayDraftValue = canonicalTextToEditorText(draftValue);
  const isTextDraftDirty =
    entry !== null && (draftsByTextKey[entry.textKey] ?? entry.value) !== entry.value;
  const isTextInputDisabled =
    entry === null ||
    !canEditText ||
    editSession === null ||
    isTextQueryPending ||
    isTextUpdating ||
    !entry.canEdit;
  useRegisterEditorDraftDirty(
    'text',
    Object.entries(draftsByTextKey).some(([textKey, value]) => {
      const sourceEntry = textKey === entry?.textKey ? entry : null;
      return sourceEntry ? value !== sourceEntry.value : true;
    })
  );

  useEffect(() => {
    if (!entry || !isTextDraftDirty) {
      return;
    }

    setDraftsByTextKey((currentDrafts) => {
      if (currentDrafts[entry.textKey] !== entry.value) {
        return currentDrafts;
      }

      const nextDrafts = { ...currentDrafts };
      delete nextDrafts[entry.textKey];
      return nextDrafts;
    });
  }, [entry, isTextDraftDirty]);

  useEffect(() => {
    const end = displayDraftValue.length;
    textValueSelectionRef.current = {
      end,
      start: end,
      textKey: entry?.textKey ?? null
    };
  }, [entry?.textKey]);

  const updateTextDraft = useCallback(
    (nextValue: string) => {
      if (!entry) {
        return;
      }

      setDraftsByTextKey((currentDrafts) => {
        if (nextValue === entry.value) {
          const nextDrafts = { ...currentDrafts };
          delete nextDrafts[entry.textKey];
          return nextDrafts;
        }

        return {
          ...currentDrafts,
          [entry.textKey]: nextValue
        };
      });
    },
    [entry]
  );

  const insertTextControlToken = useCallback(
    (token: string) => {
      if (!entry || isTextInputDisabled) {
        return;
      }

      const textarea = textValueTextareaRef.current;
      const storedSelection = textValueSelectionRef.current;
      const hasStoredSelection =
        storedSelection.textKey === entry.textKey &&
        storedSelection.start >= 0 &&
        storedSelection.end >= storedSelection.start &&
        storedSelection.end <= displayDraftValue.length;
      const selectionStart = hasStoredSelection
        ? storedSelection.start
        : displayDraftValue.length;
      const selectionEnd = hasStoredSelection ? storedSelection.end : displayDraftValue.length;
      const insertion = insertCanonicalTextControl(
        displayDraftValue,
        token,
        selectionStart,
        selectionEnd
      );
      updateTextDraft(insertion.canonicalValue);
      textValueSelectionRef.current = {
        end: insertion.cursorPosition,
        start: insertion.cursorPosition,
        textKey: entry.textKey
      };

      window.requestAnimationFrame(() => {
        textarea?.focus();
        textarea?.setSelectionRange(insertion.cursorPosition, insertion.cursorPosition);
      });
    },
    [displayDraftValue, entry, isTextInputDisabled, updateTextDraft]
  );

  const draftState = getTextDraftState(draftValue, entry, valueField);
  const canSubmit =
    editSession !== null && !isTextQueryPending && draftState.canSubmit;
  const textDraftCount = Object.keys(draftsByTextKey).length;
  const textLengthHelpId = 'selected-text-canonical-length';
  const maximumTextLength = valueField?.maximumLength ?? null;

  return (
    <aside aria-label="Selected text provenance" className="text-inspector">
      {editSession ? (
        <EditorSessionBarActions>
          <button
            aria-busy={isTextUpdating || undefined}
            className="primary-button"
            disabled={!canSubmit || isTextUpdating}
            onClick={async () => {
              if (!entry) {
                return;
              }

              const didSave = await onUpdateTextEntry(entry.textKey, draftValue);
              if (didSave) {
                setDraftsByTextKey((currentDrafts) =>
                  deleteFieldDraftRecord(currentDrafts, entry.textKey)
                );
              }
            }}
            type="button"
          >
            <BusyActionContent
              busyLabel="Staging"
              icon={<Save aria-hidden="true" size={16} />}
              isBusy={isTextUpdating}
              label="Stage"
            />
          </button>
          <button
            className="danger-button"
            disabled={isTextUpdating}
            onClick={() => cancelActiveEditSession(() => setDraftsByTextKey({}))}
            type="button"
          >
            <X aria-hidden="true" size={16} />
            <span>Cancel</span>
          </button>
          <span className="draft-action-summary">
            {textDraftCount} changed
          </span>
        </EditorSessionBarActions>
      ) : null}

      <div className="panel-heading">
        <ShieldCheck aria-hidden="true" size={18} />
        <h3>Selected Text</h3>
      </div>

      {entry ? (
        <>
          <dl className="item-provenance-list">
            <div>
              <dt>Label</dt>
              <dd data-localization-ignore="true">{entry.label}</dd>
            </div>
            {entry.messageKey ? (
              <div className="text-source-file-detail">
                <dt>{t('text.messageKey')}</dt>
                <dd data-localization-ignore="true">{entry.messageKey}</dd>
              </div>
            ) : null}
            <div className="text-source-file-detail">
              <dt>Source file</dt>
              <dd data-localization-ignore="true">{entry.sourceFile}</dd>
            </div>
            <div>
              <dt>Line</dt>
              <dd>{entry.lineIndex}</dd>
            </div>
            <div>
              <dt>Layer</dt>
              <dd>{formatSourceLayer(entry.provenance.sourceLayer)}</dd>
            </div>
            <div>
              <dt>File state</dt>
              <dd>{formatFileState(entry.provenance.fileState)}</dd>
            </div>
          </dl>

          <div className="text-edit-form">
            <div className="path-field">
              <span>{valueField?.label ?? 'Text value'}</span>
              <div aria-label="Insert text controls" className="text-token-toolbar" role="toolbar">
                {textControlInserts.map((token) => {
                  const label = t(token.labelKey);
                  return (
                    <button
                      aria-label={t('text.controls.insertAria', {
                        label,
                        syntax: token.display
                      })}
                      className="text-token-button"
                      disabled={isTextInputDisabled}
                      key={token.value}
                      onClick={() => insertTextControlToken(token.value)}
                      title={t(token.titleKey)}
                      type="button"
                    >
                      <span>{label}</span>
                      <code>{token.display}</code>
                    </button>
                  );
                })}
              </div>
              <details className="text-control-guide">
                <summary>{t('text.controls.guide.title')}</summary>
                <p>{t('text.controls.guide.help')}</p>
                <dl>
                  {textControlReference.map((control) => (
                    <div key={control.syntax}>
                      <dt>
                        <code>{control.syntax}</code>
                        <strong>{t(control.labelKey)}</strong>
                      </dt>
                      <dd>{t(control.descriptionKey)}</dd>
                    </div>
                  ))}
                </dl>
              </details>
              <textarea
                aria-describedby={maximumTextLength === null ? undefined : textLengthHelpId}
                aria-invalid={!draftState.inRange || undefined}
                aria-label={valueField?.label ?? 'Text value'}
                disabled={isTextInputDisabled}
                onChange={(event) => {
                  const normalized = normalizeEditorTextInput(
                    event.currentTarget.value,
                    event.currentTarget.selectionStart,
                    event.currentTarget.selectionEnd
                  );
                  textValueSelectionRef.current = {
                    end: normalized.selectionEnd,
                    start: normalized.selectionStart,
                    textKey: entry.textKey
                  };
                  updateTextDraft(normalized.canonicalValue);
                  window.requestAnimationFrame(() => {
                    textValueTextareaRef.current?.setSelectionRange(
                      normalized.selectionStart,
                      normalized.selectionEnd
                    );
                  });
                }}
                onSelect={(event) => {
                  textValueSelectionRef.current = {
                    end: event.currentTarget.selectionEnd,
                    start: event.currentTarget.selectionStart,
                    textKey: entry.textKey
                  };
                }}
                ref={textValueTextareaRef}
                rows={8}
                value={displayDraftValue}
              />
              {maximumTextLength === null ? null : (
                <small
                  className={`text-value-length-help ${draftState.inRange ? '' : 'is-invalid'}`}
                  id={textLengthHelpId}
                >
                  {t('text.controls.length', {
                    count: draftValue.length,
                    maximum: maximumTextLength
                  })}
                </small>
              )}
            </div>

            {!entry.canEdit ? (
              <p className="empty-copy">{entry.editBlockedReason ?? 'This text line is read-only.'}</p>
            ) : null}

          </div>
        </>
      ) : (
        <p className="empty-copy">No text entry selected.</p>
      )}
    </aside>
  );
}

type TrainerFieldUpdate = {
  field: string;
  slot: number | null;
  trainerId: number;
  value: string;
};

type TrainerPokemonSlotClipboard = {
  editorFamily: EditorUiFamily;
  sourceSlot: number;
  sourceSlotLabel: string;
  sourceTrainerId: number;
  sourceTrainerName: string;
  values: Record<string, string>;
};

type TrainerPartySlotContextMenuState = {
  left: number;
  slot: number;
  top: number;
  trainerId: number;
  triggerElement: HTMLButtonElement;
};

type ZaTrainerBulkAction = 'enableChangeAi' | 'enableCoreAi' | 'enableLastHand';

type TrainersSectionProps = {
  editSession: EditSession | null;
  editorFamily: EditorUiFamily;
  isEditStarting: boolean;
  isTrainerUpdating: boolean;
  isScarletVioletProject: boolean;
  onSearchChange: (searchText: string) => void;
  onSelectTrainer: (trainerId: number | null) => void;
  onSelectTrainerPartySlot: (slot: number | null) => void;
  onStartEditSession: () => void;
  onUpdateTrainerField: (
    trainerId: number,
    slot: number | null,
    field: string,
    value: string
  ) => void;
  onUpdateTrainerFields: (updates: TrainerFieldUpdate[]) => Promise<boolean>;
  pokemonWorkflow: PokemonWorkflow | null;
  searchText: string;
  selectedTrainerId: number | null;
  selectedTrainerPartySlot: number | null;
  workflow: TrainersWorkflow | null;
};

type TrainersSectionPublicProps = Omit<
  TrainersSectionProps,
  'editorFamily' | 'isScarletVioletProject'
>;

function SwShTrainersSection(props: TrainersSectionPublicProps) {
  return <TrainersSection {...props} editorFamily="swsh" isScarletVioletProject={false} />;
}

function SvTrainersSection(props: TrainersSectionPublicProps) {
  return <TrainersSection {...props} editorFamily="sv" isScarletVioletProject />;
}

function ZaTrainersSection(props: TrainersSectionPublicProps) {
  return <TrainersSection {...props} editorFamily="za" isScarletVioletProject={false} />;
}

function TrainersSection({
  editSession,
  editorFamily,
  isEditStarting,
  isTrainerUpdating,
  isScarletVioletProject,
  onSearchChange,
  onSelectTrainer,
  onSelectTrainerPartySlot,
  onStartEditSession,
  onUpdateTrainerField,
  onUpdateTrainerFields,
  pokemonWorkflow,
  searchText,
  selectedTrainerId,
  selectedTrainerPartySlot,
  workflow
}: TrainersSectionProps) {
  const { t } = useLocalization();
  const [selectedTrainerCategoryId, setSelectedTrainerCategoryId] = useState('all');
  const trainers = workflow?.trainers ?? [];
  const searchFilteredTrainers = useMemo(
    () => filterTrainers(trainers, searchText),
    [searchText, trainers]
  );
  const trainerCategories = useMemo(
    () => (editorFamily === 'za' ? buildZaTrainerCategories(searchFilteredTrainers) : []),
    [editorFamily, searchFilteredTrainers]
  );
  const supportsTrainerCategories = trainerCategories.length > 1;
  const activeTrainerCategoryId =
    supportsTrainerCategories &&
    trainerCategories.some((category) => category.id === selectedTrainerCategoryId)
      ? selectedTrainerCategoryId
      : 'all';
  const filteredTrainers = useMemo(
    () =>
      supportsTrainerCategories && activeTrainerCategoryId !== 'all'
        ? searchFilteredTrainers.filter(
            (trainer) => getZaTrainerCategoryId(trainer) === activeTrainerCategoryId
          )
        : searchFilteredTrainers,
    [activeTrainerCategoryId, searchFilteredTrainers, supportsTrainerCategories]
  );
  const selectedTrainerNeedsCategoryReveal =
    searchText.trim().length === 0 &&
    selectedTrainerId !== null &&
    searchFilteredTrainers.some((trainer) => trainer.trainerId === selectedTrainerId) &&
    !filteredTrainers.some((trainer) => trainer.trainerId === selectedTrainerId);
  const selectedTrainer = useMemo(
    () =>
      (selectedTrainerNeedsCategoryReveal
        ? searchFilteredTrainers.find((trainer) => trainer.trainerId === selectedTrainerId)
        : null) ??
      filteredTrainers.find((trainer) => trainer.trainerId === selectedTrainerId) ??
      filteredTrainers[0] ??
      null,
    [
      filteredTrainers,
      searchFilteredTrainers,
      selectedTrainerId,
      selectedTrainerNeedsCategoryReveal
    ]
  );
  const selectedPokemon =
    selectedTrainer?.team.find((pokemon) => pokemon.slot === selectedTrainerPartySlot) ??
    selectedTrainer?.team[0] ??
    null;
  const canEditTrainers = workflow?.summary.availability === 'available';
  const pendingTrainerIds = useMemo(
    () => getPendingTrainerIds(editSession, trainers),
    [editSession, trainers]
  );
  const [zaBulkConfirmation, setZaBulkConfirmation] =
    useState<ZaTrainerBulkAction | null>(null);
  const zaLastHandBulkUpdates = useMemo<TrainerFieldUpdate[]>(
    () =>
      editorFamily === 'za'
        ? trainers
            .filter((trainer) => trainer.zaLastHand !== true)
            .map((trainer) => ({
              field: zaLastHandFieldName,
              slot: null,
              trainerId: trainer.trainerId,
              value: '1'
            }))
        : [],
    [editorFamily, trainers]
  );
  const zaCoreAiBulkUpdates = useMemo<TrainerFieldUpdate[]>(
    () =>
      editorFamily === 'za'
        ? trainers.flatMap((trainer) => {
            const nextFlags = trainer.aiFlags | zaCoreTrainerAiMask;
            return nextFlags === trainer.aiFlags
              ? []
              : [
                  {
                    field: aiFlagsFieldName,
                    slot: null,
                    trainerId: trainer.trainerId,
                    value: nextFlags.toString()
                  }
                ];
          })
        : [],
    [editorFamily, trainers]
  );
  const zaChangeAiBulkUpdates = useMemo<TrainerFieldUpdate[]>(
    () =>
      editorFamily === 'za'
        ? trainers.flatMap((trainer) => {
            const nextFlags = trainer.aiFlags | zaChangeTrainerAiMask;
            return nextFlags === trainer.aiFlags
              ? []
              : [
                  {
                    field: aiFlagsFieldName,
                    slot: null,
                    trainerId: trainer.trainerId,
                    value: nextFlags.toString()
                  }
                ];
          })
        : [],
    [editorFamily, trainers]
  );
  const canRunZaTrainerBulkAction =
    editorFamily === 'za' &&
    editSession !== null &&
    canEditTrainers &&
    !isTrainerUpdating;

  const confirmZaTrainerBulkAction = async () => {
    if (!zaBulkConfirmation) {
      return;
    }

    const updates =
      zaBulkConfirmation === 'enableLastHand'
        ? zaLastHandBulkUpdates
        : zaBulkConfirmation === 'enableCoreAi'
          ? zaCoreAiBulkUpdates
          : zaChangeAiBulkUpdates;
    setZaBulkConfirmation(null);
    if (updates.length > 0) {
      await onUpdateTrainerFields(updates);
    }
  };

  useEffect(() => {
    if (!selectedTrainer) {
      onSelectTrainerPartySlot(null);
      return;
    }

    const hasSelectedSlot = selectedTrainer.team.some(
      (pokemon) => pokemon.slot === selectedTrainerPartySlot
    );
    if (!hasSelectedSlot) {
      onSelectTrainerPartySlot(selectedTrainer.team[0]?.slot ?? null);
    }
  }, [
    onSelectTrainerPartySlot,
    selectedTrainer?.team,
    selectedTrainer?.trainerId,
    selectedTrainerPartySlot
  ]);

  useEffect(() => {
    if (
      selectedTrainerCategoryId !== 'all' &&
      !trainerCategories.some((category) => category.id === selectedTrainerCategoryId)
    ) {
      setSelectedTrainerCategoryId('all');
    }
  }, [selectedTrainerCategoryId, trainerCategories]);

  useEffect(() => {
    if (
      selectedTrainerId !== null &&
      trainers.some((trainer) => trainer.trainerId === selectedTrainerId) &&
      !filteredTrainers.some((trainer) => trainer.trainerId === selectedTrainerId)
    ) {
      setSelectedTrainerCategoryId('all');
    }
  }, [filteredTrainers, selectedTrainerId, trainers]);

  return (
    <>
      <section
        aria-labelledby="trainers-heading"
        className={`panel wide-panel ${editorFamily}-editor-surface ${editorFamily}-trainers-section`}
      >
        <div className="panel-heading">
          <Activity aria-hidden="true" size={18} />
          <h2 id="trainers-heading">Trainers</h2>
        </div>

        <div className="items-toolbar trainers-toolbar">
          <label className="search-box items-search">
            <Search aria-hidden="true" size={18} />
            <input
              aria-label="Search trainers"
              disabled={!workflow}
              onChange={(event) => onSearchChange(event.target.value)}
              placeholder="Search trainers"
              type="search"
              value={searchText}
            />
          </label>
          <Metric
            label="Loaded trainers"
            value={workflow ? workflow.stats.totalTrainerCount.toString() : '0'}
          />
          <Metric
            label="Party Pokemon"
            value={workflow ? workflow.stats.totalPokemonCount.toString() : '0'}
          />
          <Metric
            label="Pending changes"
            value={(editSession?.pendingEdits.length ?? 0).toString()}
          />
        </div>

        {workflow ? (
          <EditorSessionBar
            canEdit={canEditTrainers && selectedTrainer !== null}
            isEditing={editSession !== null}
            isStarting={isEditStarting}
            label="Trainers"
            onStart={onStartEditSession}
          />
        ) : null}

        {workflow && editorFamily === 'za' ? (
          <div className="za-trainer-bulk-actions">
            <div className="za-trainer-bulk-actions-copy">
              <strong>{t('za.trainers.bulk.heading')}</strong>
              <small>{t('za.trainers.bulk.scopeHelp')}</small>
            </div>
            <div className="za-trainer-bulk-actions-buttons">
              <button
                className="primary-button compact-button"
                disabled={!canRunZaTrainerBulkAction || zaLastHandBulkUpdates.length === 0}
                onClick={() => setZaBulkConfirmation('enableLastHand')}
                title={
                  editSession === null
                    ? t('za.trainers.bulk.startSessionHelp')
                    : zaLastHandBulkUpdates.length === 0
                      ? t('za.trainers.bulk.lastHandAlreadyEnabled')
                      : t('za.trainers.bulk.lastHandEnableCount', {
                          count: zaLastHandBulkUpdates.length
                        })
                }
                type="button"
              >
                <ListChecks aria-hidden="true" size={14} />
                <span>{t('za.trainers.bulk.lastHandAction')}</span>
              </button>
              <button
                className="primary-button compact-button"
                disabled={!canRunZaTrainerBulkAction || zaCoreAiBulkUpdates.length === 0}
                onClick={() => setZaBulkConfirmation('enableCoreAi')}
                title={
                  editSession === null
                    ? t('za.trainers.bulk.startSessionHelp')
                    : zaCoreAiBulkUpdates.length === 0
                      ? t('za.trainers.bulk.coreAlreadyEnabled')
                      : t('za.trainers.bulk.coreEnableCount', {
                          count: zaCoreAiBulkUpdates.length
                        })
                }
                type="button"
              >
                <ShieldCheck aria-hidden="true" size={14} />
                <span>{t('za.trainers.bulk.coreAction')}</span>
              </button>
              <button
                className="primary-button compact-button"
                disabled={!canRunZaTrainerBulkAction || zaChangeAiBulkUpdates.length === 0}
                onClick={() => setZaBulkConfirmation('enableChangeAi')}
                title={
                  editSession === null
                    ? t('za.trainers.bulk.startSessionHelp')
                    : zaChangeAiBulkUpdates.length === 0
                      ? t('za.trainers.bulk.changeAlreadyEnabled')
                      : t('za.trainers.bulk.changeEnableCount', {
                          count: zaChangeAiBulkUpdates.length
                        })
                }
                type="button"
              >
                <ArrowLeftRight aria-hidden="true" size={14} />
                <span>{t('za.trainers.bulk.changeAction')}</span>
              </button>
            </div>
          </div>
        ) : null}

        {workflow ? (
          <>
            {supportsTrainerCategories ? (
              <div
                aria-label="Trainer categories"
                className="condition-tabs trainer-category-tabs"
                role="tablist"
              >
                {trainerCategories.map((category) => (
                  <button
                    aria-selected={category.id === activeTrainerCategoryId}
                    className="condition-tab-button trainer-category-tab"
                    key={category.id}
                    onClick={() => {
                      setSelectedTrainerCategoryId(category.id);
                      const nextTrainer =
                        category.id === 'all'
                          ? searchFilteredTrainers[0]
                          : searchFilteredTrainers.find(
                              (trainer) => getZaTrainerCategoryId(trainer) === category.id
                            );
                      onSelectTrainer(nextTrainer?.trainerId ?? null);
                    }}
                    role="tab"
                    title={category.description}
                    type="button"
                  >
                    <span>{category.label}</span>
                    <small>{category.count}</small>
                  </button>
                ))}
              </div>
            ) : null}

            <div className="trainers-layout">
              <div
                aria-colcount={6}
                aria-label="Trainers"
                aria-rowcount={filteredTrainers.length + 1}
                className="trainers-table"
                role="table"
              >
                <div className="trainers-row trainers-row-heading" role="row">
                  <span role="columnheader">ID</span>
                  <span role="columnheader">Name</span>
                  <span role="columnheader">Class</span>
                  <span role="columnheader">Battle</span>
                  <span role="columnheader">Team</span>
                  <span role="columnheader">Source</span>
                </div>
                <VirtualTableBody
                  getKey={(trainer) => trainer.trainerId}
                  items={filteredTrainers}
                  renderRow={(trainer) => (
                    <button
                      className={`trainers-row ${
                        selectedTrainer?.trainerId === trainer.trainerId
                          ? 'trainers-row-selected'
                          : ''
                      } ${pendingTrainerIds.has(trainer.trainerId) ? 'trainers-row-pending' : ''}`}
                      onClick={() => onSelectTrainer(trainer.trainerId)}
                      role="row"
                      type="button"
                    >
                      <span role="cell">{trainer.trainerId}</span>
                      <span data-localization-ignore="true" role="cell">
                        {trainer.name}
                      </span>
                      <span data-localization-ignore="true" role="cell">
                        {trainer.trainerClass}
                      </span>
                      <span data-localization-ignore="true" role="cell">
                        {trainer.battleType}
                      </span>
                      <span role="cell">{getOccupiedTrainerPokemonCount(trainer)}</span>
                      <span role="cell">{formatSourceLayer(trainer.provenance.sourceLayer)}</span>
                    </button>
                  )}
                />
              </div>

              <SelectedTrainerPanel
                canEditTrainers={canEditTrainers}
                editSession={editSession}
                editorFamily={editorFamily}
                editableFields={workflow.editableFields}
                isTrainerUpdating={isTrainerUpdating}
                isScarletVioletProject={isScarletVioletProject}
                onSelectSlot={onSelectTrainerPartySlot}
                onUpdateTrainerField={onUpdateTrainerField}
                onUpdateTrainerFields={onUpdateTrainerFields}
                pokemonWorkflow={pokemonWorkflow}
                selectedPokemon={selectedPokemon}
                selectedSlot={selectedTrainerPartySlot}
                trainer={selectedTrainer}
              />
            </div>
          </>
        ) : (
          <p className="empty-copy">Open Trainers from Workflows to load backend trainer data.</p>
        )}
      </section>

      <DiagnosticsSection diagnostics={workflow?.diagnostics ?? []} />
      {zaBulkConfirmation && workflow ? (
        <ZaTrainerBulkConfirmationModal
          action={zaBulkConfirmation}
          affectedCount={
            zaBulkConfirmation === 'enableLastHand'
              ? zaLastHandBulkUpdates.length
              : zaBulkConfirmation === 'enableCoreAi'
                ? zaCoreAiBulkUpdates.length
                : zaChangeAiBulkUpdates.length
          }
          isUpdating={isTrainerUpdating}
          onCancel={() => setZaBulkConfirmation(null)}
          onConfirm={confirmZaTrainerBulkAction}
          totalCount={trainers.length}
        />
      ) : null}
    </>
  );
}

function ZaTrainerBulkConfirmationModal({
  action,
  affectedCount,
  isUpdating,
  onCancel,
  onConfirm,
  totalCount
}: {
  action: ZaTrainerBulkAction;
  affectedCount: number;
  isUpdating: boolean;
  onCancel: () => void;
  onConfirm: () => void;
  totalCount: number;
}) {
  const dialogRef = useModalDialog({ onClose: onCancel });
  const { t, translateLiteral } = useLocalization();
  const enablesLastHand = action === 'enableLastHand';
  const enablesCoreAi = action === 'enableCoreAi';
  const headingId = `za-trainer-bulk-${action}-heading`;
  const title = enablesLastHand
    ? t('za.trainers.bulk.lastHandConfirmTitle')
    : enablesCoreAi
      ? t('za.trainers.bulk.coreConfirmTitle')
      : t('za.trainers.bulk.changeConfirmTitle');
  const description = enablesLastHand
    ? t('za.trainers.bulk.lastHandConfirmDescription', { affectedCount, totalCount })
    : enablesCoreAi
      ? t('za.trainers.bulk.coreConfirmDescription', { affectedCount, totalCount })
      : t('za.trainers.bulk.changeConfirmDescription', { affectedCount, totalCount });

  return (
    <div className="modal-backdrop" role="presentation">
      <section
        aria-labelledby={headingId}
        aria-modal="true"
        className="modal-panel"
        ref={dialogRef}
        role="dialog"
        tabIndex={-1}
      >
        <div className="panel-heading">
          {enablesLastHand ? (
            <ListChecks aria-hidden="true" size={18} />
          ) : enablesCoreAi ? (
            <ShieldCheck aria-hidden="true" size={18} />
          ) : (
            <ArrowLeftRight aria-hidden="true" size={18} />
          )}
          <h2 id={headingId}>{title}</h2>
        </div>
        <p className="modal-copy">{description}</p>
        <p className="modal-copy modal-copy-muted">{t('za.trainers.bulk.stagingHelp')}</p>
        <div className="modal-actions">
          <button
            aria-busy={isUpdating || undefined}
            className="primary-button"
            disabled={isUpdating || affectedCount === 0}
            onClick={onConfirm}
            type="button"
          >
            <BusyActionContent
              busyLabel={translateLiteral('Staging')}
              icon={
                enablesLastHand ? (
                  <ListChecks aria-hidden="true" size={16} />
                ) : enablesCoreAi ? (
                  <ShieldCheck aria-hidden="true" size={16} />
                ) : (
                  <ArrowLeftRight aria-hidden="true" size={16} />
                )
              }
              isBusy={isUpdating}
              label={t('za.trainers.bulk.confirmUpdates', { count: affectedCount })}
            />
          </button>
          <button className="secondary-button" disabled={isUpdating} onClick={onCancel} type="button">
            <X aria-hidden="true" size={16} />
            <span>{translateLiteral('Cancel')}</span>
          </button>
        </div>
      </section>
    </div>
  );
}

function SelectedTrainerPanel({
  canEditTrainers,
  editSession,
  editorFamily,
  editableFields,
  isTrainerUpdating,
  isScarletVioletProject,
  onSelectSlot,
  onUpdateTrainerField,
  onUpdateTrainerFields,
  pokemonWorkflow,
  selectedPokemon,
  selectedSlot,
  trainer
}: {
  canEditTrainers: boolean;
  editSession: EditSession | null;
  editorFamily: EditorUiFamily;
  editableFields: TrainerEditableField[];
  isTrainerUpdating: boolean;
  isScarletVioletProject: boolean;
  onSelectSlot: (slot: number | null) => void;
  onUpdateTrainerField: (
    trainerId: number,
    slot: number | null,
    field: string,
    value: string
  ) => void;
  onUpdateTrainerFields: (updates: TrainerFieldUpdate[]) => Promise<boolean>;
  pokemonWorkflow: PokemonWorkflow | null;
  selectedPokemon: TrainerPokemonRecord | null;
  selectedSlot: number | null;
  trainer: TrainerRecord | null;
}) {
  const { formatLocale, t, translateLiteral } = useLocalization();
  const [trainerDraftsByTrainerId, setTrainerDraftsByTrainerId] = useState<
    Record<string, Record<string, string>>
  >({});
  const [pokemonDraftsByTrainerSlot, setPokemonDraftsByTrainerSlot] = useState<
    Record<string, Record<string, string>>
  >({});
  const [partySlotClipboard, setPartySlotClipboard] =
    useState<TrainerPokemonSlotClipboard | null>(null);
  const [partySlotContextMenu, setPartySlotContextMenu] =
    useState<TrainerPartySlotContextMenuState | null>(null);
  const [partySlotClipboardFeedback, setPartySlotClipboardFeedback] = useState<string | null>(
    null
  );
  const cancelActiveEditSession = useCancelActiveEditSession();
  const trainerFields = useMemo(
    () =>
      editableFields.filter((field) =>
        trainerDataFieldNames.includes(field.field as (typeof trainerDataFieldNames)[number])
      ),
    [editableFields]
  );
  const pokemonFields = useMemo(
    () =>
      editableFields.filter((field) =>
        trainerPokemonFieldNames.includes(field.field as (typeof trainerPokemonFieldNames)[number])
      ),
    [editableFields]
  );
  const defaultContextualPokemonFields = useMemo(
    () =>
      pokemonFields.map((field) => {
        const options = getContextualFieldOptions(
          field,
          selectedPokemon
            ? {
                abilityOptions: selectedPokemon.abilityOptions,
                formOptions: selectedPokemon.formOptions,
                gameFamily: editorFamily,
                species: selectedPokemon.species,
                speciesId: selectedPokemon.speciesId
              }
            : undefined
        );

        return options === field.options ? field : { ...field, options };
      }),
    [editorFamily, pokemonFields, selectedPokemon]
  );
  const trainerDraftDefaults = useMemo(
    () =>
      trainer
        ? createTrainerDrafts(trainerFields, (field) =>
            getEditableTrainerFieldValue(trainer, field)
          )
        : {},
    [trainer, trainerFields]
  );
  const pokemonDraftDefaults = useMemo(
    () =>
      selectedPokemon
        ? createTrainerDrafts(defaultContextualPokemonFields, (field) =>
            getEditablePokemonFieldValue(selectedPokemon, field)
          )
        : {},
    [defaultContextualPokemonFields, selectedPokemon]
  );
  const selectedPokemonDraftKey =
    trainer && selectedPokemon ? `${trainer.trainerId}:${selectedPokemon.slot}` : null;
  const trainerDrafts = trainer
    ? trainerDraftsByTrainerId[trainer.trainerId.toString()] ?? trainerDraftDefaults
    : {};
  const pokemonDrafts = selectedPokemonDraftKey
    ? pokemonDraftsByTrainerSlot[selectedPokemonDraftKey] ?? pokemonDraftDefaults
    : {};
  const projectedSelectedPokemonSpeciesId = selectedPokemon
    ? (getProjectedTrainerPokemonFieldValue(
        selectedPokemon,
        defaultContextualPokemonFields,
        pokemonDrafts,
        speciesIdFieldName
      ) ?? selectedPokemon.speciesId)
    : null;
  const projectedSelectedPokemonGender = selectedPokemon
    ? (getProjectedTrainerPokemonFieldValue(
        selectedPokemon,
        defaultContextualPokemonFields,
        pokemonDrafts,
        genderFieldName
      ) ?? selectedPokemon.gender)
    : null;
  const isSelectedZaTrainerMeowstic = Boolean(
    editorFamily === 'za' && projectedSelectedPokemonSpeciesId === zaMeowsticSpeciesId
  );
  const isSelectedZaTrainerMeowsticDynamic =
    isSelectedZaTrainerMeowstic && projectedSelectedPokemonGender === 0;
  const selectedPokemonFormOptionContext = useMemo(
    () => {
      if (!selectedPokemon) {
        return undefined;
      }

      const context = createDraftSpeciesFormOptionContext(
        defaultContextualPokemonFields.find(
          (field) => field.field === speciesIdFieldName
        ) ?? null,
        pokemonDrafts[speciesIdFieldName],
        selectedPokemon.species,
        selectedPokemon.speciesId,
        selectedPokemon.abilityOptions,
        editorFamily,
        undefined,
        selectedPokemon.formOptions
      );
      const draftedForm = Number.parseInt(
        pokemonDrafts[formFieldName] ?? selectedPokemon.form.toString(),
        10
      );
      const referencePokemon = pokemonWorkflow?.pokemon.find(
        (pokemon) =>
          pokemon.speciesId === context.speciesId &&
          pokemon.form === (Number.isInteger(draftedForm) ? draftedForm : selectedPokemon.form)
      );
      const usesCurrentIdentity =
        context.speciesId === selectedPokemon.speciesId &&
        draftedForm === selectedPokemon.form;
      const zaTrainerMeowstic =
        editorFamily === 'za' && context.speciesId === zaMeowsticSpeciesId;
      const genderOptions = zaTrainerMeowstic
        ? (pokemonFields.find((field) => field.field === genderFieldName)?.options ?? []).map(
            (option) =>
              option.value === 0
                ? {
                    ...option,
                    label: t('za.trainers.meowstic.defaultGenderOption')
                  }
                : option
          )
        : undefined;
      const allowedFormValues = zaTrainerMeowstic
        ? getZaTrainerMeowsticFormsForGender(projectedSelectedPokemonGender)
        : undefined;
      const formLabelOverrides =
        zaTrainerMeowstic && projectedSelectedPokemonGender === 0
          ? {
              [draftedForm]: t('za.trainers.meowstic.defaultFormOption')
            }
          : undefined;

      return {
        ...context,
        abilityOptions: referencePokemon
          ? createTrainerPokemonAbilityOptions(referencePokemon)
          : usesCurrentIdentity
            ? selectedPokemon.abilityOptions
            : [],
        allowedFormValues,
        formLabelOverrides,
        genderOptions
      };
    },
    [
      defaultContextualPokemonFields,
      editorFamily,
      pokemonFields,
      pokemonDrafts,
      pokemonWorkflow,
      projectedSelectedPokemonGender,
      selectedPokemon,
      t
    ]
  );
  const contextualPokemonFields = useMemo(
    () =>
      pokemonFields.map((field) => {
        const options = getContextualFieldOptions(field, selectedPokemonFormOptionContext);
        return options === field.options ? field : { ...field, options };
      }),
    [pokemonFields, selectedPokemonFormOptionContext]
  );
  const projectedTrainerHighestLevel = useMemo(
    () => getProjectedTrainerHighestLevel(trainer, pokemonFields, pokemonDraftsByTrainerSlot),
    [pokemonDraftsByTrainerSlot, pokemonFields, trainer]
  );
  const contextualTrainerFields = useMemo(
    () =>
      trainerFields.map((field) =>
        field.field === moneyFieldName
          ? {
              ...field,
              label:
                editorFamily === 'swsh'
                  ? 'Prize money rate'
                  : editorFamily === 'za'
                    ? 'Base prize money'
                    : field.label,
              options:
                editorFamily === 'za'
                  ? createZaTrainerPrizeMoneyOptions(projectedTrainerHighestLevel, formatLocale)
                  : field.options
            }
          : field
      ),
    [editorFamily, formatLocale, projectedTrainerHighestLevel, trainerFields]
  );
  const aiFlagsField = editableFields.find((field) => field.field === aiFlagsFieldName) ?? null;
  const canToggleAiFlags =
    canEditTrainers && editSession !== null && !isTrainerUpdating && aiFlagsField !== null;
  const aiFlagsMaskLabel = trainer
    ? `0x${trainer.aiFlags.toString(16).padStart(4, '0').toLocaleUpperCase()}`
    : '0x0000';
  const showTerastallizationDetails =
    isScarletVioletProject &&
    contextualTrainerFields.some((field) => field.field === trainerCanTerastallizeFieldName);
  const trainerFieldGroups = useMemo(
    () => groupTrainerEditableFields(contextualTrainerFields, getTrainerDataFieldGroup),
    [contextualTrainerFields]
  );
  const pokemonFieldGroups = useMemo(
    () =>
      groupTrainerEditableFields(contextualPokemonFields, getTrainerPokemonFieldGroup).map(
        sortTrainerPokemonFieldGroup
      ),
    [contextualPokemonFields]
  );
  const pokemonNatureEffects = useMemo(() => {
    if (!selectedPokemon) {
      return null;
    }

    const natureField =
      contextualPokemonFields.find((field) => field.field === natureFieldName) ?? null;
    const natureDraftValue = pokemonDrafts[natureFieldName] ?? selectedPokemon.nature.toString();
    return getNatureStatEffects(
      parseEditableIntegerDraft(natureDraftValue, natureField?.options),
      editorFamily
    );
  }, [contextualPokemonFields, editorFamily, pokemonDrafts, selectedPokemon]);
  const projectedPokemonStats = useMemo(
    () =>
      selectedPokemon
        ? getProjectedTrainerPokemonStats(
            selectedPokemon,
            contextualPokemonFields,
            pokemonDrafts,
            pokemonWorkflow,
            editorFamily
          )
        : null,
    [contextualPokemonFields, editorFamily, pokemonDrafts, pokemonWorkflow, selectedPokemon]
  );
  const selectedPokemonCanDynamax = useMemo(() => {
    if (!selectedPokemon) {
      return true;
    }

    const pokemonCanDynamaxField =
      contextualPokemonFields.find((field) => field.field === canDynamaxFieldName) ?? null;
    if (!pokemonCanDynamaxField) {
      return true;
    }

    const currentValue = getEditablePokemonFieldValue(selectedPokemon, canDynamaxFieldName);
    const draftValue =
      pokemonDrafts[canDynamaxFieldName] ?? currentValue?.toString() ?? '';
    const draftState = getTrainerFieldDraftState(
      draftValue,
      currentValue,
      pokemonCanDynamaxField
    );

    if (!draftState.isValid || draftState.normalizedValue === null) {
      return currentValue === 1;
    }

    return draftState.normalizedValue === '1';
  }, [contextualPokemonFields, pokemonDrafts, selectedPokemon]);
  const selectedPokemonBlockedByPreviousSlot = useMemo(() => {
    if (!trainer || !selectedPokemon) {
      return false;
    }

    return trainer.team.some(
      (pokemon) => pokemon.slot < selectedPokemon.slot && pokemon.speciesId === 0
    );
  }, [selectedPokemon, trainer]);
  const contextMenuPokemon =
    partySlotContextMenu && trainer?.trainerId === partySlotContextMenu.trainerId
      ? trainer.team.find((pokemon) => pokemon.slot === partySlotContextMenu.slot) ?? null
      : null;
  const contextMenuPokemonDraftKey =
    trainer && contextMenuPokemon ? `${trainer.trainerId}:${contextMenuPokemon.slot}` : null;
  const contextMenuPokemonDrafts =
    contextMenuPokemonDraftKey === null
      ? undefined
      : pokemonDraftsByTrainerSlot[contextMenuPokemonDraftKey];
  const contextMenuPokemonValues =
    contextMenuPokemon === null
      ? null
      : createTrainerPokemonSlotClipboardValues(
          contextMenuPokemon,
          pokemonFields,
          contextMenuPokemonDrafts
        );
  const contextMenuTargetBlockedByPreviousSlot = Boolean(
    trainer &&
      contextMenuPokemon &&
      trainer.team.some(
        (pokemon) => pokemon.slot < contextMenuPokemon.slot && pokemon.speciesId === 0
      )
  );
  const contextMenuCommonDisabledReason =
    !canEditTrainers || pokemonFields.length === 0
      ? t('trainers.partyClipboard.unavailableReason')
      : editSession === null
        ? t('trainers.partyClipboard.startSessionReason')
        : isTrainerUpdating
          ? t('trainers.partyClipboard.busyReason')
          : contextMenuPokemon === null
            ? t('trainers.partyClipboard.unavailableReason')
            : undefined;
  const contextMenuPokemonHasInvalidDrafts = Boolean(
    contextMenuPokemon &&
      contextMenuPokemonValues &&
      hasInvalidTrainerPokemonDrafts(
        editorFamily,
        contextualPokemonFields,
        contextMenuPokemonValues,
        (field) => getEditablePokemonFieldValue(contextMenuPokemon, field)
      )
  );
  const contextMenuCopyDisabledReason =
    contextMenuCommonDisabledReason ??
    (contextMenuPokemon &&
    contextMenuPokemonValues &&
    isTrainerPokemonSlotEmpty(contextMenuPokemon, contextMenuPokemonValues, pokemonFields)
      ? t('trainers.partyClipboard.emptySourceReason')
      : contextMenuPokemonHasInvalidDrafts
        ? t('trainers.partyClipboard.invalidSourceReason')
        : undefined);
  const contextMenuPasteDisabledReason =
    contextMenuCommonDisabledReason ??
    (partySlotClipboard === null
      ? t('trainers.partyClipboard.noSourceReason')
      : partySlotClipboard.editorFamily !== editorFamily
        ? t('trainers.partyClipboard.incompatibleReason')
        : trainer &&
            contextMenuPokemon &&
            partySlotClipboard.sourceTrainerId === trainer.trainerId &&
            partySlotClipboard.sourceSlot === contextMenuPokemon.slot
          ? t('trainers.partyClipboard.sameSlotReason')
          : contextMenuTargetBlockedByPreviousSlot
            ? t('trainers.partyClipboard.blockedTargetReason')
            : undefined);
  const partySlotClipboardSourceLabel = partySlotClipboard
    ? t('trainers.partyClipboard.sourceSummary', {
        slot: partySlotClipboard.sourceSlotLabel,
        trainer: partySlotClipboard.sourceTrainerName
      })
    : null;
  const partySlotClipboardCopiedLabel = partySlotClipboard
    ? t('trainers.partyClipboard.copiedFeedback', {
        slot: partySlotClipboard.sourceSlotLabel,
        trainer: partySlotClipboard.sourceTrainerName
      })
    : null;
  const contextMenuTargetLabel =
    trainer && contextMenuPokemon
      ? t('trainers.partyClipboard.targetSummary', {
          slot: formatTrainerSlotNumber(contextMenuPokemon.slot, editorFamily),
          trainer: trainer.name
        })
      : t('trainers.partyClipboard.unavailableTarget');
  const trainerDraftSummary = useMemo(
    () =>
      getTrainerDraftSummary(
        contextualTrainerFields,
        trainerDrafts,
        trainer ? (field) => getEditableTrainerFieldValue(trainer, field) : null
      ),
    [contextualTrainerFields, trainer, trainerDrafts]
  );
  const pokemonDraftSummary = useMemo(
    () =>
      getTrainerDraftSummary(
        contextualPokemonFields,
        pokemonDrafts,
        selectedPokemon ? (field) => getEditablePokemonFieldValue(selectedPokemon, field) : null
      ),
    [contextualPokemonFields, pokemonDrafts, selectedPokemon]
  );
  const pokemonHasInvalidEvTotal = useMemo(
    () =>
      editorFamily === 'za' &&
      selectedPokemon !== null &&
      hasChangedPokemonEvTotalOverLimit(
        contextualPokemonFields,
        pokemonDrafts,
        (field) => getEditablePokemonFieldValue(selectedPokemon, field)
      ),
    [contextualPokemonFields, editorFamily, pokemonDrafts, selectedPokemon]
  );
  const canSaveTrainerDrafts =
    trainer !== null &&
    editSession !== null &&
    canEditTrainers &&
    !isTrainerUpdating &&
    trainerDraftSummary.changedFields.length > 0 &&
    trainerDraftSummary.invalidFields.length === 0;
  const canSavePokemonDrafts =
    trainer !== null &&
    selectedPokemon !== null &&
    editSession !== null &&
    canEditTrainers &&
    !isTrainerUpdating &&
    pokemonDraftSummary.changedFields.length > 0 &&
    pokemonDraftSummary.invalidFields.length === 0 &&
    !pokemonHasInvalidEvTotal;
  const trainerMaxIvUpdates = useMemo(
    () => createTrainerMaxIvUpdates(trainer, contextualPokemonFields),
    [contextualPokemonFields, trainer]
  );
  const hasTrainerMaxIvDraftChanges = useMemo(
    () =>
      hasTrainerNonMaxIvDrafts(
        pokemonDraftsByTrainerSlot,
        trainer,
        contextualPokemonFields
      ),
    [contextualPokemonFields, pokemonDraftsByTrainerSlot, trainer]
  );
  const canMaxTrainerIvs =
    trainer !== null &&
    editSession !== null &&
    canEditTrainers &&
    !isTrainerUpdating &&
    (trainerMaxIvUpdates.length > 0 || hasTrainerMaxIvDraftChanges);
  useRegisterEditorDraftDirty(
    'trainers',
    countFieldDraftRecords(trainerDraftsByTrainerId) > 0 ||
      countFieldDraftRecords(pokemonDraftsByTrainerSlot) > 0
  );

  const closePartySlotContextMenu = useCallback(() => {
    setPartySlotContextMenu(null);
  }, []);

  useEffect(() => {
    setPartySlotContextMenu(null);
  }, [trainer?.trainerId]);

  useEffect(() => {
    if (editSession !== null) {
      return;
    }

    setPartySlotClipboard(null);
    setPartySlotClipboardFeedback(null);
    setPartySlotContextMenu(null);
  }, [editSession]);

  useEffect(() => {
    setPartySlotClipboard((currentClipboard) =>
      currentClipboard?.editorFamily === editorFamily ? currentClipboard : null
    );
    setPartySlotClipboardFeedback(null);
    setPartySlotContextMenu(null);
  }, [editorFamily]);

  useEffect(() => {
    if (!trainer) {
      return;
    }

    setTrainerDraftsByTrainerId((currentDrafts) =>
      pruneFieldDraftRecord(currentDrafts, trainer.trainerId, trainerDraftDefaults)
    );
  }, [trainer, trainerDraftDefaults]);

  useEffect(() => {
    if (!selectedPokemonDraftKey) {
      return;
    }

    setPokemonDraftsByTrainerSlot((currentDrafts) =>
      pruneFieldDraftRecord(currentDrafts, selectedPokemonDraftKey, pokemonDraftDefaults)
    );
  }, [pokemonDraftDefaults, selectedPokemonDraftKey]);

  const stageTrainerDrafts = async () => {
    if (!trainer) {
      return;
    }

    const didSave = await onUpdateTrainerFields(
      trainerDraftSummary.changedFields.map((change) => ({
        field: change.field,
        slot: null,
        trainerId: trainer.trainerId,
        value: change.value
      }))
    );
    if (didSave) {
      setTrainerDraftsByTrainerId((currentDrafts) =>
        deleteFieldDraftRecord(currentDrafts, trainer.trainerId)
      );
    }
  };

  const stagePokemonDrafts = async () => {
    if (!canSavePokemonDrafts || !trainer || !selectedPokemon) {
      return;
    }

    const didSave = await onUpdateTrainerFields(
      pokemonDraftSummary.changedFields.map((change) => ({
        field: change.field,
        slot: selectedPokemon.slot,
        trainerId: trainer.trainerId,
        value: change.value
      }))
    );
    if (didSave && selectedPokemonDraftKey) {
      setPokemonDraftsByTrainerSlot((currentDrafts) =>
        deleteFieldDraftRecord(currentDrafts, selectedPokemonDraftKey)
      );
    }
  };

  const stageTrainerMaxIvs = async () => {
    if (!trainer) {
      return;
    }

    const didSave =
      trainerMaxIvUpdates.length === 0 ||
      (await onUpdateTrainerFields(trainerMaxIvUpdates));
    if (didSave) {
      setPokemonDraftsByTrainerSlot((currentDrafts) =>
        reconcileTrainerMaxIvDrafts(
          currentDrafts,
          trainer,
          contextualPokemonFields
        )
      );
    }
  };

  const openPartySlotContextMenu = (
    pokemon: TrainerPokemonRecord,
    triggerElement: HTMLButtonElement,
    left: number,
    top: number
  ) => {
    if (!trainer) {
      return;
    }

    onSelectSlot(pokemon.slot);
    setPartySlotContextMenu({
      left,
      slot: pokemon.slot,
      top,
      trainerId: trainer.trainerId,
      triggerElement
    });
  };

  const copyPartySlot = () => {
    if (
      contextMenuCopyDisabledReason !== undefined ||
      !trainer ||
      !contextMenuPokemon ||
      !contextMenuPokemonValues
    ) {
      return;
    }

    const sourceSlotLabel = formatTrainerSlotNumber(
      contextMenuPokemon.slot,
      editorFamily
    ).toString();
    setPartySlotClipboard({
      editorFamily,
      sourceSlot: contextMenuPokemon.slot,
      sourceSlotLabel,
      sourceTrainerId: trainer.trainerId,
      sourceTrainerName: trainer.name,
      values: contextMenuPokemonValues
    });
    setPartySlotClipboardFeedback(null);
  };

  const pastePartySlot = () => {
    if (
      contextMenuPasteDisabledReason !== undefined ||
      !trainer ||
      !contextMenuPokemon ||
      !contextMenuPokemonDraftKey ||
      !partySlotClipboard
    ) {
      return;
    }

    const destinationDefaults = createTrainerPokemonSlotClipboardValues(
      contextMenuPokemon,
      pokemonFields
    );
    const nextDrafts = Object.fromEntries(
      pokemonFields.map((field) => [
        field.field,
        partySlotClipboard.values[field.field] ?? destinationDefaults[field.field] ?? ''
      ])
    );
    setPokemonDraftsByTrainerSlot((currentDrafts) =>
      setFieldDraftRecord(
        currentDrafts,
        contextMenuPokemonDraftKey,
        nextDrafts,
        destinationDefaults
      )
    );
    onSelectSlot(contextMenuPokemon.slot);
    setPartySlotClipboardFeedback(
      t('trainers.partyClipboard.pastedFeedback', {
        slot: formatTrainerSlotNumber(contextMenuPokemon.slot, editorFamily),
        trainer: trainer.name
      })
    );
  };

  const cancelTrainerEdit = () =>
    cancelActiveEditSession(() => {
      setTrainerDraftsByTrainerId({});
      setPokemonDraftsByTrainerSlot({});
    });

  return (
    <aside aria-label="Selected trainer provenance" className="trainer-inspector">
      {editSession ? (
        <EditorSessionBarActions>
          <button
            aria-busy={isTrainerUpdating || undefined}
            className="primary-button"
            disabled={!canSaveTrainerDrafts}
            onClick={stageTrainerDrafts}
            type="button"
          >
            <BusyActionContent
              busyLabel="Staging"
              icon={<Save aria-hidden="true" size={16} />}
              isBusy={isTrainerUpdating}
              label="Stage Trainer"
            />
          </button>
          {selectedPokemon ? (
            <button
              aria-busy={isTrainerUpdating || undefined}
              className="primary-button"
              disabled={!canSavePokemonDrafts}
              onClick={stagePokemonDrafts}
              type="button"
            >
              <BusyActionContent
                busyLabel="Staging"
                icon={<Save aria-hidden="true" size={16} />}
                isBusy={isTrainerUpdating}
                label="Stage Party"
              />
            </button>
          ) : null}
          <button
            className="danger-button"
            disabled={isTrainerUpdating}
            onClick={cancelTrainerEdit}
            type="button"
          >
            <X aria-hidden="true" size={16} />
            <span>Cancel</span>
          </button>
          <span className="draft-action-summary">
            Trainer: {formatDraftSummary(trainerDraftSummary)}
            {selectedPokemon
              ? `; party: ${formatDraftSummary(pokemonDraftSummary)}`
              : ''}
          </span>
        </EditorSessionBarActions>
      ) : null}
      <div className="panel-heading">
        <ShieldCheck aria-hidden="true" size={18} />
        <h3>Selected Trainer</h3>
      </div>

      {trainer ? (
        <>
          <dl className="item-provenance-list">
            <div>
              <dt>Name</dt>
              <dd data-localization-ignore="true">{trainer.name}</dd>
            </div>
            <div>
              <dt>Data file</dt>
              <dd>{trainer.provenance.sourceFile}</dd>
            </div>
            <div>
              <dt>Party file</dt>
              <dd>{trainer.provenance.teamSourceFile}</dd>
            </div>
            <div>
              <dt>Class file</dt>
              <dd>{trainer.provenance.classSourceFile ?? 'Not loaded'}</dd>
            </div>
            <div>
              <dt>Class ball scope</dt>
              <dd>{trainer.classBallScope}</dd>
            </div>
            {showTerastallizationDetails ? (
              <>
                <div>
                  <dt>Can Terastallize</dt>
                  <dd>{trainer.canTerastallize === true ? 'Yes' : 'No'}</dd>
                </div>
                <div>
                  <dt>Tera behavior</dt>
                  <dd>{trainer.teraTarget ?? 'Disabled'}</dd>
                </div>
              </>
            ) : null}
            <div>
              <dt>Data layer</dt>
              <dd>{formatSourceLayer(trainer.provenance.sourceLayer)}</dd>
            </div>
            <div>
              <dt>Party layer</dt>
              <dd>{formatSourceLayer(trainer.provenance.teamSourceLayer)}</dd>
            </div>
            <div>
              <dt>Class layer</dt>
              <dd>
                {trainer.provenance.classSourceLayer
                  ? formatSourceLayer(trainer.provenance.classSourceLayer)
                  : 'Not loaded'}
              </dd>
            </div>
          </dl>

          {editorFamily === 'za' && trainer.zaSharedRivalRoster === true ? (
            <section
              aria-labelledby="za-shared-rival-roster-heading"
              className="technical-tool-notice technical-tool-notice-info za-shared-rival-notice"
            >
              <div className="technical-tool-notice-heading">
                <UsersRound aria-hidden="true" size={18} />
                <div>
                  <h3 id="za-shared-rival-roster-heading">
                    {t('za.trainers.sharedRival.title')}
                  </h3>
                  <p>
                    <strong>{t('za.trainers.sharedRival.recordIdLabel')}</strong>{' '}
                    <code data-localization-ignore="true">{trainer.location}</code>
                  </p>
                </div>
              </div>
              <div className="za-shared-rival-notice-facts">
                <p>{t('za.trainers.sharedRival.selection')}</p>
                {trainer.zaRivalStarterBranch ? (
                  <p>
                    {t('za.trainers.sharedRival.starterBranch', {
                      branch: t(
                        `za.trainers.sharedRival.starter.${trainer.zaRivalStarterBranch}`
                      )
                    })}
                  </p>
                ) : null}
                <p>{t('za.trainers.sharedRival.editScope')}</p>
                <p>{t('za.trainers.sharedRival.meowsticAvailability')}</p>
                {trainer.team.some((pokemon) => pokemon.speciesId === zaMeowsticSpeciesId) ? (
                  <p>{t('za.trainers.sharedRival.meowstic')}</p>
                ) : (
                  <p>{t('za.trainers.sharedRival.meowsticAbsent')}</p>
                )}
              </div>
            </section>
          ) : null}

          <div className="trainer-edit-form">
            {trainer.aiFlagStates.length > 0 ? (
              <div className="trainer-ai-flags-panel">
                <div className="trainer-ai-flags-header">
                  <div className="editable-field-label-row">
                    <strong>{translateLiteral('AI Flags')}</strong>
                    <ContextHelp label={translateLiteral('AI Flags')}>
                      {t('fieldHelp.catalog.trainer.ai')}
                    </ContextHelp>
                  </div>
                  <span>{aiFlagsMaskLabel}</span>
                </div>
                <div className="trainer-ai-flags-grid">
                  {trainer.aiFlagStates.map((flag) => {
                    const isReserved = flag.label.toLocaleLowerCase().startsWith('unused');
                    const flagInputId = `trainer-${trainer.trainerId}-ai-flag-${flag.bit}`;
                    const localizedFlagLabel = translateLiteral(flag.label);
                    const localizedFlagHelp = isReserved
                      ? `${translateLiteral('Reserved for later research.')} ${translateLiteral(
                          'Reserved and locked.'
                        )}`
                      : translateLiteral(flag.description);

                    return (
                      <div
                        className={`trainer-ai-flag ${
                          isReserved ? 'trainer-ai-flag-disabled' : ''
                        }`}
                        key={flag.bit}
                      >
                        <input
                          checked={flag.enabled}
                          className="km-choice-control"
                          disabled={!canToggleAiFlags || isReserved}
                          id={flagInputId}
                          onChange={(event) => {
                            const nextValue = event.target.checked
                              ? trainer.aiFlags | flag.mask
                              : trainer.aiFlags & ~flag.mask;
                            onUpdateTrainerField(
                              trainer.trainerId,
                              null,
                              aiFlagsFieldName,
                              nextValue.toString()
                            );
                          }}
                          type="checkbox"
                        />
                        <div className="trainer-ai-flag-copy">
                          <FieldLabel
                            help={localizedFlagHelp}
                            htmlFor={flagInputId}
                            label={localizedFlagLabel}
                          />
                          {isReserved ? (
                            <small>{translateLiteral('Reserved and locked.')}</small>
                          ) : null}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            ) : null}

            <div className="editable-field-groups">
              {trainerFieldGroups.map((group) => (
                <fieldset className="editable-field-group" key={group.group}>
                  <legend>{group.group}</legend>
                  <div className="editable-field-grid">
                    {group.fields.map((field) => {
                      const currentValue = getEditableTrainerFieldValue(trainer, field.field);
                      const draftValue = trainerDrafts[field.field] ?? '';
                      const draftState = getTrainerFieldDraftState(draftValue, currentValue, field);
                      const isFieldBlocked =
                        field.field === classBallIdFieldName && !trainer.canEditClassBall;
                      const disabledReason =
                        editorFamily === 'swsh' && field.field === giftFieldName
                          ? 'This unknown trainer header value is preserved as raw read-only data.'
                          : editorFamily === 'swsh' && field.field === healFieldName
                            ? 'This unknown trainer header flag is preserved as raw read-only data.'
                          : isFieldBlocked
                          ? 'Class ball is locked for this trainer class.'
                          : undefined;

                      return (
                        <TrainerDraftField
                          currentValue={currentValue}
                          disabled={
                            disabledReason !== undefined ||
                            !canEditTrainers ||
                            editSession === null ||
                            isTrainerUpdating
                          }
                          disabledReason={disabledReason}
                          draftState={draftState}
                          draftValue={draftValue}
                          field={field}
                          helpDomain="trainers"
                          helpGame={editorFamily}
                          key={field.field}
                          onChange={(value) => {
                            const nextDrafts = {
                              ...trainerDrafts,
                              [field.field]: value
                            };
                            setTrainerDraftsByTrainerId((currentDrafts) =>
                              setFieldDraftRecord(
                                currentDrafts,
                                trainer.trainerId,
                                nextDrafts,
                                trainerDraftDefaults
                              )
                            );
                          }}
                        />
                      );
                    })}
                  </div>
                </fieldset>
              ))}
            </div>
            <div className="trainer-party-header">
              <strong>Party</strong>
              <div
                aria-live="polite"
                className="trainer-party-clipboard-status"
                role="status"
              >
                <span
                  className={
                    partySlotClipboardCopiedLabel
                      ? 'trainer-party-clipboard-source is-copied'
                      : 'trainer-party-clipboard-source'
                  }
                >
                  {partySlotClipboardCopiedLabel ??
                    t('trainers.partyClipboard.discoveryHint')}
                </span>
                {partySlotClipboardFeedback ? (
                  <small>{partySlotClipboardFeedback}</small>
                ) : null}
              </div>
              <button
                aria-busy={isTrainerUpdating || undefined}
                className="primary-button compact-button trainer-max-iv-button"
                disabled={!canMaxTrainerIvs}
                onClick={stageTrainerMaxIvs}
                type="button"
              >
                <BusyActionContent
                  busyLabel="Staging"
                  icon={<Sparkles aria-hidden="true" size={14} />}
                  isBusy={isTrainerUpdating}
                  label="MAX IV"
                />
              </button>
            </div>

            {trainer.team.length > 0 ? (
              <div className="trainer-party-card-grid" aria-label="Trainer party Pokemon">
                {trainer.team.map((pokemon) => {
                  const cardDrafts =
                    pokemonDraftsByTrainerSlot[`${trainer.trainerId}:${pokemon.slot}`] ?? {};
                  const hasCardDrafts = Object.keys(cardDrafts).length > 0;
                  const projectedPokemon = getProjectedTrainerPokemonCardIdentity(
                    pokemon,
                    pokemonFields,
                    cardDrafts,
                    pokemonWorkflow,
                    editorFamily
                  );
                  const isEmptySlot = projectedPokemon.speciesId === 0;
                  const projectedHeldItemId = isEmptySlot ? 0 : projectedPokemon.heldItemId;
                  const projectedHeldItemLabel =
                    projectedHeldItemId === 0
                      ? t('trainers.partyCard.noHeldItem')
                      : t('trainers.partyCard.heldItem', {
                          item: projectedPokemon.heldItem ?? projectedHeldItemId.toString()
                        });
                  const isDynamicZaTrainerMeowstic =
                    editorFamily === 'za' &&
                    projectedPokemon.speciesId === zaMeowsticSpeciesId &&
                    projectedPokemon.gender === 0;
                  const pokemonLabel = isEmptySlot
                    ? 'Empty slot'
                    : isDynamicZaTrainerMeowstic
                      ? t('za.trainers.meowstic.cardLabel')
                      : formatSpeciesFormLabel(
                          projectedPokemon.species,
                          projectedPokemon.form,
                          projectedPokemon.speciesId,
                          editorFamily
                        );
                  const pokemonSpriteLabel = isEmptySlot
                    ? 'None'
                    : formatSpeciesFormLabel(
                        projectedPokemon.spriteName ?? projectedPokemon.species,
                        projectedPokemon.form,
                        projectedPokemon.speciesId,
                        editorFamily
                      );
                  const slotLabel = `Slot ${formatTrainerSlotNumber(pokemon.slot, editorFamily)}`;
                  const isCopiedSource = Boolean(
                    partySlotClipboard?.sourceTrainerId === trainer.trainerId &&
                      partySlotClipboard.sourceSlot === pokemon.slot
                  );
                  const isContextMenuTarget = Boolean(
                    partySlotContextMenu?.trainerId === trainer.trainerId &&
                      partySlotContextMenu.slot === pokemon.slot
                  );

                  return (
                    <button
                      aria-controls={
                        isContextMenuTarget ? trainerPartySlotContextMenuId : undefined
                      }
                      aria-expanded={isContextMenuTarget || undefined}
                      aria-haspopup="menu"
                      aria-keyshortcuts="Shift+F10"
                      aria-pressed={selectedSlot === pokemon.slot}
                      className={`trainer-party-card ${
                        isCopiedSource ? 'trainer-party-card-copy-source' : ''
                      }`.trim()}
                      key={pokemon.slot}
                      onClick={() => onSelectSlot(pokemon.slot)}
                      onContextMenu={(event) => {
                        event.preventDefault();
                        openPartySlotContextMenu(
                          pokemon,
                          event.currentTarget,
                          event.clientX,
                          event.clientY
                        );
                      }}
                      onKeyDown={(event) => {
                        if (
                          event.key !== 'ContextMenu' &&
                          !(event.shiftKey && event.key === 'F10')
                        ) {
                          return;
                        }

                        event.preventDefault();
                        const bounds = event.currentTarget.getBoundingClientRect();
                        openPartySlotContextMenu(
                          pokemon,
                          event.currentTarget,
                          bounds.left + Math.min(28, bounds.width / 2),
                          bounds.top + Math.min(28, bounds.height / 2)
                        );
                      }}
                      type="button"
                    >
                      <PokemonSprite
                        editorFamily={editorFamily}
                        className="trainer-party-sprite"
                        form={projectedPokemon.form}
                        name={pokemonLabel}
                        speciesId={projectedPokemon.speciesId}
                        spriteName={projectedPokemon.spriteName ?? pokemonSpriteLabel}
                      />
                      <strong data-localization-ignore="true">
                        {isEmptySlot ? slotLabel : pokemonLabel}
                      </strong>
                      <span>
                        {isEmptySlot ? 'None' : `Lv. ${projectedPokemon.level}`}
                        {hasCardDrafts ? ` (${translateLiteral('Draft')})` : ''}
                      </span>
                      {projectedHeldItemId > 0 ? (
                        <span
                          aria-hidden="true"
                          className="trainer-party-held-item-bag"
                          title={projectedHeldItemLabel}
                        >
                          <HeldItemSprite
                            editorFamily={editorFamily}
                            itemId={projectedHeldItemId}
                          />
                        </span>
                      ) : null}
                      <span className="trainer-party-held-item-accessibility">
                        {projectedHeldItemLabel}
                      </span>
                    </button>
                  );
                })}
              </div>
            ) : null}

            {selectedPokemon ? (
              <div className="trainer-party-edit-stack">
                {isSelectedZaTrainerMeowstic ? (
                  <section className="technical-tool-notice technical-tool-notice-info">
                    <div className="technical-tool-notice-heading">
                      <UsersRound aria-hidden="true" size={18} />
                      <div>
                        <h3>{t('za.trainers.meowstic.detailsTitle')}</h3>
                        <p>
                          {t(
                            isSelectedZaTrainerMeowsticDynamic &&
                              trainer.zaSharedRivalRoster === true
                              ? 'za.trainers.sharedRival.meowstic.detailsDynamic'
                              : isSelectedZaTrainerMeowsticDynamic
                                ? 'za.trainers.meowstic.detailsDynamic'
                                : 'za.trainers.meowstic.detailsExplicit'
                          )}
                        </p>
                      </div>
                    </div>
                  </section>
                ) : null}
                <div className="editable-field-groups">
                  {pokemonFieldGroups.map((group) => (
                    <fieldset className="editable-field-group" key={group.group}>
                      <legend>
                        <span className="editable-field-group-legend-content">
                          <span>{group.group}</span>
                          {editorFamily === 'za' && group.group === 'Stats - EVs' ? (
                            <PokemonStatTotal
                              drafts={pokemonDrafts}
                              fields={group.fields}
                              getValue={(fieldName) =>
                                getEditablePokemonFieldValue(selectedPokemon, fieldName)
                              }
                              kind="ev"
                            />
                          ) : editorFamily === 'za' && group.group === 'Stats - IVs' ? (
                            <PokemonStatTotal
                              drafts={pokemonDrafts}
                              fields={group.fields}
                              getValue={(fieldName) =>
                                getEditablePokemonFieldValue(selectedPokemon, fieldName)
                              }
                              kind="iv"
                            />
                          ) : null}
                        </span>
                      </legend>
                      <div className="editable-field-grid">
                        {group.fields.map((field) => {
                          const currentValue = getEditablePokemonFieldValue(
                            selectedPokemon,
                            field.field
                          );
                          const draftValue = pokemonDrafts[field.field] ?? '';
                          const draftState = getTrainerFieldDraftState(
                            draftValue,
                            currentValue,
                            field
                          );
                          const isDynamaxDependentField = dynamaxDependentFieldNames.includes(
                            field.field as (typeof dynamaxDependentFieldNames)[number]
                          );
                          const selectedPokemonSlotIsEmpty =
                            projectedSelectedPokemonSpeciesId === 0;
                          const disabledReason =
                            selectedPokemonBlockedByPreviousSlot
                              ? 'Fill the previous party slot first.'
                              : selectedPokemonSlotIsEmpty && field.field !== speciesIdFieldName
                              ? 'Set species before editing this slot.'
                              : isSelectedZaTrainerMeowsticDynamic &&
                                  field.field === formFieldName
                                ? t(
                                    'za.trainers.meowstic.formRuntimeSelected'
                                  )
                                : isDynamaxDependentField && !selectedPokemonCanDynamax
                                  ? 'Set Can Dynamax to Yes to edit this field.'
                                  : undefined;

                          return (
                            <TrainerDraftField
                              currentValue={currentValue}
                              disabled={
                                disabledReason !== undefined ||
                                !canEditTrainers ||
                                editSession === null ||
                                isTrainerUpdating
                              }
                              disabledReason={disabledReason}
                              draftState={draftState}
                              draftValue={draftValue}
                              field={field}
                                formOptionContext={selectedPokemonFormOptionContext}
                                helpDomain="trainers"
                                helpGame={editorFamily}
                                key={field.field}
                              labelAdornment={getNatureStatAdornment(
                                field.field,
                                pokemonNatureEffects
                              )}
                              onChange={(value) => {
                                if (!selectedPokemonDraftKey) {
                                  return;
                                }

                                const nextDrafts = {
                                  ...pokemonDrafts,
                                  [field.field]: value
                                };
                                if (field.field === speciesIdFieldName) {
                                  const speciesField = defaultContextualPokemonFields.find(
                                    (candidate) => candidate.field === speciesIdFieldName
                                  );
                                  const formField = defaultContextualPokemonFields.find(
                                    (candidate) => candidate.field === formFieldName
                                  );
                                  const previousSpeciesId =
                                    parseEditableIntegerDraft(
                                      pokemonDrafts[speciesIdFieldName] ??
                                        selectedPokemon.speciesId.toString(),
                                      speciesField?.options
                                    );
                                  const targetSpeciesId = parseEditableIntegerDraft(
                                    value,
                                    speciesField?.options
                                  );
                                  const previousForm =
                                    parseOptionalInteger(
                                      pokemonDrafts[formFieldName] ??
                                        selectedPokemon.form.toString()
                                    ) ?? selectedPokemon.form;

                                  if (targetSpeciesId === 0) {
                                    for (const dependentField of defaultContextualPokemonFields) {
                                      if (dependentField.field !== speciesIdFieldName) {
                                        nextDrafts[dependentField.field] =
                                          pokemonDraftDefaults[dependentField.field] ?? '';
                                      }
                                    }
                                  } else if (
                                    formField &&
                                    targetSpeciesId !== null &&
                                    targetSpeciesId !== previousSpeciesId
                                  ) {
                                    const resolvedForm = resolveSpeciesChangeForm({
                                      gameFamily: editorFamily,
                                      pokemonRecords: pokemonWorkflow?.pokemon,
                                      previousForm,
                                      sourceForm: selectedPokemon.form,
                                      sourceSpeciesId: selectedPokemon.speciesId,
                                      speciesField,
                                      targetSpeciesId
                                    });
                                    if (resolvedForm !== null) {
                                      nextDrafts[formFieldName] = resolvedForm.toString();
                                    }
                                  }
                                }
                                if (
                                  editorFamily === 'za' &&
                                  (field.field === speciesIdFieldName ||
                                    field.field === genderFieldName)
                                ) {
                                  const nextSpeciesId =
                                    parseOptionalInteger(
                                      nextDrafts[speciesIdFieldName] ??
                                        selectedPokemon.speciesId.toString()
                                    ) ?? selectedPokemon.speciesId;
                                  const nextGender =
                                    parseOptionalInteger(
                                      nextDrafts[genderFieldName] ??
                                        selectedPokemon.gender.toString()
                                    ) ?? selectedPokemon.gender;
                                  const nextForm =
                                    parseOptionalInteger(
                                      nextDrafts[formFieldName] ??
                                        selectedPokemon.form.toString()
                                    ) ?? selectedPokemon.form;

                                  if (nextSpeciesId === zaMeowsticSpeciesId) {
                                    if (nextGender === 0) {
                                      nextDrafts[formFieldName] = '0';
                                    } else if (nextGender === 1 || nextGender === 2) {
                                      nextDrafts[formFieldName] =
                                        resolveZaTrainerMeowsticFormForGender(
                                          nextGender,
                                          nextForm
                                        ).toString();
                                    }
                                  }
                                }
                                if (field.field === canDynamaxFieldName && value === '0') {
                                  for (const dependentField of dynamaxDependentFieldNames) {
                                    nextDrafts[dependentField] =
                                      pokemonDraftDefaults[dependentField] ?? '';
                                  }
                                }
                                setPokemonDraftsByTrainerSlot((currentDrafts) =>
                                  setFieldDraftRecord(
                                    currentDrafts,
                                    selectedPokemonDraftKey,
                                    nextDrafts,
                                    pokemonDraftDefaults
                                  )
                                );
                              }}
                            />
                          );
                        })}
                      </div>
                    </fieldset>
                  ))}
                </div>
                <TrainerPokemonProjectedStatsPanel projectedStats={projectedPokemonStats} />
              </div>
            ) : (
              <p className="empty-copy">No party Pokemon selected.</p>
            )}

          </div>
        </>
      ) : (
        <p className="empty-copy">No trainer selected.</p>
      )}
      {partySlotContextMenu ? (
        <TrainerPartySlotContextMenu
          copyDisabledReason={contextMenuCopyDisabledReason}
          left={partySlotContextMenu.left}
          onClose={closePartySlotContextMenu}
          onCopy={copyPartySlot}
          onPaste={pastePartySlot}
          pasteDisabledReason={contextMenuPasteDisabledReason}
          sourceLabel={partySlotClipboardSourceLabel ?? undefined}
          targetLabel={contextMenuTargetLabel}
          top={partySlotContextMenu.top}
          triggerElement={partySlotContextMenu.triggerElement}
        />
      ) : null}
    </aside>
  );
}

type TrainerDraftState = {
  error: string | null;
  isChanged: boolean;
  isValid: boolean;
  normalizedValue: string | null;
};

type TrainerDraftChange = {
  field: string;
  label: string;
  value: string;
};

type PokemonStatTotalState = {
  hasChangedValue: boolean;
  isAvailable: boolean;
  isOverLimit: boolean;
  total: number;
};

function getPokemonStatTotalState(
  drafts: Record<string, string>,
  fields: NumericEditableField[],
  getValue: (fieldName: string) => number | null,
  kind: 'ev' | 'iv'
): PokemonStatTotalState | null {
  const fieldNames = kind === 'ev' ? evFieldNames : ivFieldNames;
  const maximumTotal = kind === 'ev' ? maximumPokemonEvTotal : maximumPokemonIvTotal;
  const statFields = fieldNames
    .map((fieldName) => fields.find((field) => field.field === fieldName) ?? null)
    .filter((field): field is NumericEditableField => field !== null);
  if (statFields.length !== fieldNames.length) {
    return null;
  }

  let hasChangedValue = false;
  let total = 0;
  for (const field of statFields) {
    const currentValue = getValue(field.field);
    const draftValue = Object.prototype.hasOwnProperty.call(drafts, field.field)
      ? drafts[field.field]
      : currentValue?.toString() ?? '';
    const draftState = getTrainerFieldDraftState(draftValue, currentValue, field);
    const parsedValue =
      draftState.normalizedValue === null
        ? null
        : parseEditableIntegerDraft(draftState.normalizedValue, field.options);
    if (
      !draftState.isValid ||
      parsedValue === null ||
      (kind === 'iv' && parsedValue === -1)
    ) {
      return {
        hasChangedValue: hasChangedValue || draftState.isChanged,
        isAvailable: false,
        isOverLimit: false,
        total: 0
      };
    }

    hasChangedValue ||= draftState.isChanged;
    total += parsedValue;
  }

  return {
    hasChangedValue,
    isAvailable: true,
    isOverLimit: total > maximumTotal,
    total
  };
}

function hasChangedPokemonEvTotalOverLimit(
  fields: NumericEditableField[],
  drafts: Record<string, string>,
  getValue: (fieldName: string) => number | null
) {
  const state = getPokemonStatTotalState(drafts, fields, getValue, 'ev');
  return state?.hasChangedValue === true && state.isOverLimit;
}

function hasInvalidTrainerPokemonDrafts(
  editorFamily: EditorUiFamily,
  fields: NumericEditableField[],
  drafts: Record<string, string>,
  getValue: (fieldName: string) => number | null
) {
  const summary = getTrainerDraftSummary(fields, drafts, getValue);
  return (
    summary.invalidFields.length > 0 ||
    (editorFamily === 'za' && hasChangedPokemonEvTotalOverLimit(fields, drafts, getValue))
  );
}

function PokemonStatTotal({
  drafts,
  fields,
  getValue,
  kind
}: {
  drafts: Record<string, string>;
  fields: NumericEditableField[];
  getValue: (fieldName: string) => number | null;
  kind: 'ev' | 'iv';
}) {
  const { t } = useLocalization();
  const state = getPokemonStatTotalState(drafts, fields, getValue, kind);
  if (state === null) {
    return null;
  }

  const maximumTotal = kind === 'ev' ? maximumPokemonEvTotal : maximumPokemonIvTotal;
  const value = state.isAvailable
    ? kind === 'ev'
      ? t('pokemon.evTotal.value', { maximum: maximumTotal, total: state.total })
      : t('pokemon.ivTotal.value', { maximum: maximumTotal, total: state.total })
    : kind === 'ev'
      ? t('pokemon.evTotal.unavailable')
      : t('pokemon.ivTotal.unavailable');
  const overLimit = state.isOverLimit
    ? kind === 'ev'
      ? t('pokemon.evTotal.overLimit', { amount: state.total - maximumTotal })
      : t('pokemon.ivTotal.overLimit', { amount: state.total - maximumTotal })
    : null;
  return (
    <span
      aria-atomic="true"
      aria-live="polite"
      className={`pokemon-stat-total ${state.isOverLimit ? 'is-over-limit' : ''}`}
      role="status"
    >
      <span>{value}</span>
      {overLimit ? <span className="pokemon-stat-total-over-limit">{overLimit}</span> : null}
    </span>
  );
}

type ProjectedTrainerPokemonStats = {
  baseStats: NonNullable<TrainerPokemonRecord['baseStats']>;
  stats: TrainerPokemonRecord['evs'];
};

function TrainerPokemonProjectedStatsPanel({
  projectedStats
}: {
  projectedStats: ProjectedTrainerPokemonStats | null;
}) {
  const { translateLiteral } = useLocalization();

  if (!projectedStats) {
    return null;
  }

  return (
    <section aria-label="Projected stats" className="trainer-projected-stats-panel">
      <div className="trainer-projected-stats-header">
        <strong>{translateLiteral('Projected Stats')}</strong>
      </div>
      <dl className="trainer-projected-stats-grid">
        {trainerProjectedStatRows.map((row) => (
          <div className="trainer-projected-stat" key={row.key}>
            <dt>{translateLiteral(row.label)}</dt>
            <dd aria-label={`${row.label} projected stat`}>
              {projectedStats.stats[row.key]}
            </dd>
          </div>
        ))}
      </dl>
    </section>
  );
}
type DynamaxAdventureEditableFieldName = DynamaxAdventureEditableField['field'];
type DynamaxAdventureEntryChangeGroup = {
  entryIndex: number;
  changes: Array<{ field: DynamaxAdventureEditableFieldName; value: string }>;
};
type DynamaxAdventureDraftFieldOptions = Record<string, EditableFieldOption[]>;

type DraftStateContext = {
  clampIvStats?: boolean;
  drafts: Record<string, string>;
  enforcePokemonEvLimits?: boolean;
  fields: NumericEditableField[];
  getValue: (field: string) => number | null;
  preservedValues?: Readonly<Record<string, number | null>>;
};

type NumericEditableField = {
  field: string;
  label: string;
  maximumValue: number | null;
  minimumValue: number | null;
  options: EditableFieldOption[];
  valueKind: string;
};

function TrainerDraftField({
  currentValue,
  disabled,
  disabledReason,
  draftState,
  draftValue,
  emptyOptionLabel,
  field,
  formOptionContext,
  helpDomain,
  helpGame,
  idPrefix = 'trainer-field',
  labelAdornment,
  onChange
}: {
  currentValue: number | null;
  disabled: boolean;
  disabledReason?: string;
  draftState: TrainerDraftState;
  draftValue: string;
  emptyOptionLabel?: string;
  field: NumericEditableField;
  formOptionContext?: SpeciesFormOptionContext;
  helpDomain?: FieldHelpDomain;
  helpGame?: FieldHelpGame;
  idPrefix?: string;
  labelAdornment?: ReactNode;
  onChange: (value: string) => void;
}) {
  const inputId = `${idPrefix}-${field.field}`;
  const { contextualFormOptionContext, options } =
    useContextualSpeciesFormOptions(field, formOptionContext, currentValue);
  const formDisabledReason = getFormFieldDisabledReason(
    field,
    contextualFormOptionContext,
    draftValue,
    options
  );
  const effectiveDisabledReason = disabledReason ?? formDisabledReason ?? undefined;
  const effectiveDisabled = disabled || Boolean(effectiveDisabledReason);
  const statusText = draftState.error ?? (draftState.isChanged ? 'Changed' : null);
  const { t, translateLiteral } = useLocalization();
  const localizedFieldLabel = translateLiteral(field.label);
  const localizedFieldHelpText = translateLiteral(
    effectiveDisabledReason ??
      getEditableFieldHelp(field, t, {
        domain: helpDomain,
        game: helpGame ?? formOptionContext?.gameFamily,
        label: localizedFieldLabel,
        optionCount: options.length
      })
  );
  const localizedFieldHoverText = effectiveDisabledReason
    ? translateLiteral(effectiveDisabledReason)
    : getEditableFieldHoverHelp(field, t, {
        domain: helpDomain,
        game: helpGame ?? formOptionContext?.gameFamily,
        label: localizedFieldLabel,
        optionCount: options.length
      });

  return (
    <div
      className={`path-field editable-field-control ${
        draftState.isChanged ? 'editable-field-changed' : ''
      } ${!draftState.isValid ? 'editable-field-invalid' : ''} ${
        effectiveDisabledReason ? 'editable-field-disabled' : ''
      }`}
    >
      <FieldLabel
        adornment={labelAdornment}
        help={localizedFieldHelpText}
        htmlFor={inputId}
        label={localizedFieldLabel}
      />
      {field.valueKind === 'boolean' ? (
        <HoverTooltip content={localizedFieldHoverText}>
          <select
            aria-label={localizedFieldLabel}
            className="km-select-control"
            disabled={effectiveDisabled}
            id={inputId}
            onChange={(event) => onChange(event.target.value)}
            value={draftValue === '1' ? '1' : '0'}
          >
            <option value="1">{translateLiteral('Yes')}</option>
            <option value="0">{translateLiteral('No')}</option>
          </select>
        </HoverTooltip>
      ) : options.length > 0 ? (
        <SearchableOptionInput
          ariaLabel={field.label}
          disabled={effectiveDisabled}
          emptyOptionLabel={emptyOptionLabel}
          id={inputId}
          onChange={onChange}
          options={options}
          value={draftValue}
        />
      ) : (
        <HoverTooltip content={localizedFieldHoverText}>
          <input
            aria-label={localizedFieldLabel}
            disabled={effectiveDisabled}
            id={inputId}
            max={field.maximumValue ?? undefined}
            min={field.minimumValue ?? undefined}
            onChange={(event) => onChange(event.target.value)}
            type="number"
            value={draftValue}
          />
        </HoverTooltip>
      )}
      {effectiveDisabledReason ? (
        <small className="editable-field-status">{translateLiteral(effectiveDisabledReason)}</small>
      ) : statusText ? (
        <small className={draftState.error ? 'editable-field-error' : 'editable-field-status'}>
          {translateLiteral(statusText)}
        </small>
      ) : null}
    </div>
  );
}

function getZaTrainerMeowsticFormsForGender(gender: number | null) {
  if (gender === 1) {
    return [0, 2];
  }

  if (gender === 2) {
    return [1, 3];
  }

  return undefined;
}

function resolveZaTrainerMeowsticFormForGender(gender: number, form: number) {
  const isMegaForm = form === 2 || form === 3;
  if (gender === 1) {
    return isMegaForm ? 2 : 0;
  }

  if (gender === 2) {
    return isMegaForm ? 3 : 1;
  }

  return form;
}

function createTrainerDrafts(
  fields: NumericEditableField[],
  getValue: (field: string) => number | null
) {
  return Object.fromEntries(
    fields.map((field) => [field.field, (getValue(field.field) ?? '').toString()])
  );
}

function createPokemonInstanceDrafts(
  fields: NumericEditableField[],
  getValue: (field: string) => number | null
) {
  return Object.fromEntries(
    fields.map((field) => {
      const value = getValue(field.field);
      return [
        field.field,
        value === null && isPokemonInstanceIvPresetField(field.field)
          ? ivPresetCustomOptionValue.toString()
          : (value ?? '').toString()
      ];
    })
  );
}

function withPokemonInstanceIvPresetOptions<T extends NumericEditableField>(field: T): T {
  if (!isPokemonInstanceIvPresetField(field.field)) {
    return field;
  }

  if (field.options.some((option) => option.value === ivPresetCustomOptionValue)) {
    return field;
  }

  return {
    ...field,
    options: [...field.options, ivPresetCustomOption]
  };
}

function withDynamaxAdventureSpeciesOptions<T extends NumericEditableField>(
  field: T,
  encounter: DynamaxAdventureRecord | null,
  safeNormalSpeciesOptions: EditableFieldOption[],
  fieldOptions: DynamaxAdventureDraftFieldOptions
): T {
  const overrideOptions = fieldOptions[field.field];
  if (overrideOptions !== undefined) {
    return { ...field, options: overrideOptions };
  }

  if (
    encounter !== null &&
    staticEncounterMoveFieldNames.includes(
      field.field as (typeof staticEncounterMoveFieldNames)[number]
    )
  ) {
    return { ...field, options: encounter.moveOptions };
  }

  if (field.field === abilityFieldName && encounter !== null) {
    return { ...field, options: encounter.abilityOptions };
  }

  if (field.field === dynamaxAdventureGigantamaxStateFieldName && encounter !== null) {
    return { ...field, options: encounter.gigantamaxOptions };
  }

  if (field.field !== giftSpeciesFieldName || encounter === null) {
    return field;
  }

  if (safeNormalSpeciesOptions.length === 0) {
    return { ...field, options: [] };
  }

  const options = [...safeNormalSpeciesOptions];
  const selectedIdentityOptions = [
    {
      label: `${encounter.speciesId.toString().padStart(3, '0')} ${encounter.species}`,
      value: encounter.speciesId
    },
    ...(encounter.vanillaPokemon
      ? [
          {
            label: `${encounter.vanillaPokemon.speciesId.toString().padStart(3, '0')} ${encounter.vanillaPokemon.species}`,
            value: encounter.vanillaPokemon.speciesId
          }
        ]
      : [])
  ];
  for (const option of selectedIdentityOptions) {
    if (!options.some((candidate) => candidate.value === option.value)) {
      options.push(option);
    }
  }
  options.sort((left, right) => left.value - right.value);
  return { ...field, options };
}

function isPokemonInstanceIvPresetField(fieldName: string) {
  return (
    fieldName === giftFlawlessIvCountFieldName ||
    fieldName === rentalFixedIvPresetFieldName ||
    fieldName === dynamaxAdventureGuaranteedPerfectIvsFieldName
  );
}

function isPokemonInstanceIvStatField(fieldName: string) {
  return (
    ivFieldNames.includes(fieldName as (typeof ivFieldNames)[number]) ||
    dynamaxAdventureIvFieldNames.includes(
      fieldName as (typeof dynamaxAdventureIvFieldNames)[number]
    )
  );
}

function getPokemonInstanceIvPresetFieldName(fields: NumericEditableField[]) {
  return (
    fields.find((field) => isPokemonInstanceIvPresetField(field.field))?.field ?? null
  );
}

function isPokemonInstanceIvCustomSelected(
  fields: NumericEditableField[],
  drafts: Record<string, string>
) {
  const presetFieldName = getPokemonInstanceIvPresetFieldName(fields);
  return (
    presetFieldName !== null &&
    parseEditableIntegerDraft(drafts[presetFieldName] ?? '', [
      ivPresetCustomOption
    ]) === ivPresetCustomOptionValue
  );
}

function getActivePokemonInstanceFields(
  fields: NumericEditableField[],
  drafts: Record<string, string>
) {
  if (isPokemonInstanceIvCustomSelected(fields, drafts)) {
    return fields;
  }

  return fields.filter((field) => !isPokemonInstanceIvStatField(field.field));
}

function getPokemonInstanceIvStatDisabledReason(
  fieldName: string,
  fields: NumericEditableField[],
  drafts: Record<string, string>
) {
  if (!isPokemonInstanceIvStatField(fieldName)) {
    return null;
  }

  if (getPokemonInstanceIvPresetFieldName(fields) === null) {
    return null;
  }

  return isPokemonInstanceIvCustomSelected(fields, drafts)
    ? null
    : 'Select Custom in IV preset to edit individual IVs.';
}

function normalizePokemonStatDraftValue(
  fieldName: string,
  value: number,
  context?: DraftStateContext
) {
  if (context?.clampIvStats && isPokemonIvStatField(fieldName)) {
    if (
      value === -1 &&
      dynamaxAdventureIvFieldNames.includes(
        fieldName as (typeof dynamaxAdventureIvFieldNames)[number]
      )
    ) {
      return value;
    }

    return clampInteger(value, 0, maximumPokemonIvValue);
  }

  if (context?.enforcePokemonEvLimits && isPokemonEvStatField(fieldName)) {
    return clampPokemonEvDraftValue(fieldName, value, context);
  }

  return value;
}

function clampPokemonEvDraftValue(
  fieldName: string,
  value: number,
  context: DraftStateContext
) {
  const otherEvTotal = evFieldNames
    .filter((candidate) => candidate !== fieldName)
    .reduce((total, otherFieldName) => {
      const otherField = context.fields.find((field) => field.field === otherFieldName);
      const parsedDraft =
        otherField === undefined
          ? null
          : parseEditableIntegerDraft(context.drafts[otherFieldName] ?? '', otherField.options);
      const fallbackValue = context.getValue(otherFieldName) ?? 0;
      const effectiveValue = parsedDraft ?? fallbackValue;
      return total + clampInteger(effectiveValue, 0, maximumPokemonEvValue);
    }, 0);
  const remainingBudget = Math.max(0, maximumPokemonEvTotal - otherEvTotal);

  return Math.min(clampInteger(value, 0, maximumPokemonEvValue), remainingBudget);
}

function isPokemonIvStatField(fieldName: string) {
  return (
    ivFieldNames.includes(fieldName as (typeof ivFieldNames)[number]) ||
    dynamaxAdventureIvFieldNames.includes(
      fieldName as (typeof dynamaxAdventureIvFieldNames)[number]
    )
  );
}

function isPokemonEvStatField(fieldName: string) {
  return evFieldNames.includes(fieldName as (typeof evFieldNames)[number]);
}

function clampInteger(value: number, minimum: number, maximum: number) {
  return Math.min(Math.max(value, minimum), maximum);
}

function getProjectedTrainerHighestLevel(
  trainer: TrainerRecord | null,
  fields: TrainerEditableField[],
  draftsByTrainerSlot: Record<string, Record<string, string>>
) {
  if (!trainer || trainer.team.length === 0) {
    return 0;
  }

  return Math.max(
    ...trainer.team.map((pokemon) => {
      const drafts = draftsByTrainerSlot[`${trainer.trainerId}:${pokemon.slot}`] ?? {};
      const speciesId =
        getProjectedTrainerPokemonFieldValue(pokemon, fields, drafts, speciesIdFieldName) ??
        pokemon.speciesId;
      if (speciesId === 0) {
        return 0;
      }

      return (
        getProjectedTrainerPokemonFieldValue(pokemon, fields, drafts, levelFieldName) ??
        pokemon.level
      );
    })
  );
}

function getOccupiedTrainerPokemonCount(trainer: TrainerRecord) {
  return trainer.team.filter((pokemon) => pokemon.speciesId > 0).length;
}

function createTrainerMaxIvUpdates(
  trainer: TrainerRecord | null,
  fields: TrainerEditableField[]
): TrainerFieldUpdate[] {
  if (!trainer) {
    return [];
  }

  const editableIvFields = getEditableTrainerIvFields(fields);

  return trainer.team
    .filter((pokemon) => pokemon.speciesId > 0)
    .flatMap((pokemon) =>
      editableIvFields
        .filter(
          (field) => getEditablePokemonFieldValue(pokemon, field) !== maximumPokemonIvValue
        )
        .map((field) => ({
          field,
          slot: pokemon.slot,
          trainerId: trainer.trainerId,
          value: maximumPokemonIvValue.toString()
        }))
    );
}

function reconcileTrainerMaxIvDrafts(
  records: Record<string, Record<string, string>>,
  trainer: TrainerRecord,
  fields: TrainerEditableField[]
) {
  const editableIvFields = getEditableTrainerIvFields(fields);
  let nextRecords = records;

  for (const pokemon of trainer.team) {
    if (pokemon.speciesId <= 0) {
      continue;
    }

    const recordKey = `${trainer.trainerId}:${pokemon.slot}`;
    const currentDrafts = nextRecords[recordKey];
    if (!currentDrafts) {
      continue;
    }

    const nextDrafts = { ...currentDrafts };
    const nextDefaults = createTrainerDrafts(fields, (field) =>
      getEditablePokemonFieldValue(pokemon, field)
    );
    for (const field of editableIvFields) {
      nextDrafts[field] = maximumPokemonIvValue.toString();
      nextDefaults[field] = maximumPokemonIvValue.toString();
    }

    nextRecords = setFieldDraftRecord(nextRecords, recordKey, nextDrafts, nextDefaults);
  }

  return nextRecords;
}

function hasTrainerNonMaxIvDrafts(
  records: Record<string, Record<string, string>>,
  trainer: TrainerRecord | null,
  fields: TrainerEditableField[]
) {
  if (!trainer) {
    return false;
  }

  const editableIvFields = getEditableTrainerIvFields(fields);

  return trainer.team
    .filter((pokemon) => pokemon.speciesId > 0)
    .some((pokemon) => {
      const drafts = records[`${trainer.trainerId}:${pokemon.slot}`];
      return (
        drafts !== undefined &&
        editableIvFields.some(
          (field) =>
            drafts[field] !== undefined &&
            drafts[field].trim() !== maximumPokemonIvValue.toString()
        )
      );
    });
}

function getEditableTrainerIvFields(fields: TrainerEditableField[]) {
  return fields
    .map((field) => field.field)
    .filter((field): field is (typeof ivFieldNames)[number] =>
      ivFieldNames.includes(field as (typeof ivFieldNames)[number])
    );
}

function formatTrainerSlotNumber(slot: number, editorFamily: EditorUiFamily) {
  return editorFamily === 'swsh' ? slot : slot + 1;
}

function createTrainerPokemonSlotClipboardValues(
  pokemon: TrainerPokemonRecord,
  fields: TrainerEditableField[],
  drafts?: Record<string, string>
) {
  return Object.fromEntries(
    fields.map((field) => [
      field.field,
      drafts?.[field.field] ??
        (getEditablePokemonFieldValue(pokemon, field.field) ?? '').toString()
    ])
  );
}

function isTrainerPokemonSlotEmpty(
  pokemon: TrainerPokemonRecord,
  values: Record<string, string>,
  fields: TrainerEditableField[]
) {
  const speciesField = fields.find((field) => field.field === speciesIdFieldName);
  const draftedSpeciesId = parseEditableIntegerDraft(
    values[speciesIdFieldName] ?? pokemon.speciesId.toString(),
    speciesField?.options
  );
  return (draftedSpeciesId ?? pokemon.speciesId) === 0;
}

function createZaTrainerPrizeMoneyOptions(
  highestLevel: number,
  formatLocale: string
): EditableFieldOption[] {
  const normalizedHighestLevel = Math.max(1, highestLevel);

  return Array.from({ length: 256 }, (_, rate) => {
    const payout = getZaTrainerBasePrizeMoney(normalizedHighestLevel, rate);

    return {
      label: `$${payout.toLocaleString(formatLocale)} (rate ${rate})`,
      value: rate
    };
  });
}

function getZaTrainerBasePrizeMoney(highestLevel: number, rate: number) {
  return highestLevel * rate * 4;
}

type NumericEditableFieldSource = EditableFieldWithOptions & {
  field: string;
  valueKind: string;
};

function toNumericEditableControlField(
  field: NumericEditableFieldSource,
  optionsOverride?: EditableFieldOption[]
): NumericEditableField {
  return {
    field: field.field,
    label: field.label,
    maximumValue: field.maximumValue ?? null,
    minimumValue: field.minimumValue ?? null,
    options: optionsOverride ?? field.options ?? [],
    valueKind: field.valueKind
  };
}

function groupTrainerEditableFields(
  fields: TrainerEditableField[],
  getGroup: (field: TrainerEditableField) => string
) {
  const groups: Array<{ group: string; fields: TrainerEditableField[] }> = [];

  for (const field of fields) {
    const groupName = getGroup(field);
    let group = groups.find((candidate) => candidate.group === groupName);
    if (!group) {
      group = { group: groupName, fields: [] };
      groups.push(group);
    }

    group.fields.push(field);
  }

  return groups;
}

function sortTrainerPokemonFieldGroup(group: {
  group: string;
  fields: TrainerEditableField[];
}) {
  if (group.group !== 'Traits') {
    return group;
  }

  const traitOrder = new Map(
    [
      genderFieldName,
      abilityFieldName,
      natureFieldName,
      trainerTeraTypeFieldName,
      canDynamaxFieldName,
      dynamaxLevelFieldName,
      canGigantamaxFieldName,
      shinyFieldName
    ].map((fieldName, index) => [fieldName, index])
  );

  return {
    ...group,
    fields: [...group.fields].sort(
      (left, right) =>
        (traitOrder.get(left.field) ?? Number.MAX_SAFE_INTEGER) -
        (traitOrder.get(right.field) ?? Number.MAX_SAFE_INTEGER)
    )
  };
}

type NatureStatKey = keyof typeof natureStatLabels;

type NatureStatEffects = {
  down: NatureStatKey | null;
  up: NatureStatKey | null;
};

function getNatureStatEffects(
  nature: number | null,
  editorFamily: EditorUiFamily = 'swsh'
): NatureStatEffects | null {
  const effects: Record<number, NatureStatEffects> = {
    1: { up: 'attack', down: 'defense' },
    2: { up: 'attack', down: 'speed' },
    3: { up: 'attack', down: 'specialAttack' },
    4: { up: 'attack', down: 'specialDefense' },
    5: { up: 'defense', down: 'attack' },
    7: { up: 'defense', down: 'speed' },
    8: { up: 'defense', down: 'specialAttack' },
    9: { up: 'defense', down: 'specialDefense' },
    10: { up: 'speed', down: 'attack' },
    11: { up: 'speed', down: 'defense' },
    13: { up: 'speed', down: 'specialAttack' },
    14: { up: 'speed', down: 'specialDefense' },
    15: { up: 'specialAttack', down: 'attack' },
    16: { up: 'specialAttack', down: 'defense' },
    17: { up: 'specialAttack', down: 'speed' },
    19: { up: 'specialAttack', down: 'specialDefense' },
    20: { up: 'specialDefense', down: 'attack' },
    21: { up: 'specialDefense', down: 'defense' },
    22: { up: 'specialDefense', down: 'speed' },
    23: { up: 'specialDefense', down: 'specialAttack' }
  };

  if (nature === null) {
    return null;
  }

  const normalizedNature =
    (editorFamily === 'sv' || editorFamily === 'za') && nature > 0 ? nature - 1 : nature;
  return effects[normalizedNature] ?? { up: null, down: null };
}

function getProjectedTrainerPokemonCardIdentity(
  pokemon: TrainerPokemonRecord,
  fields: TrainerEditableField[],
  drafts: Record<string, string>,
  pokemonWorkflow: PokemonWorkflow | null,
  editorFamily: EditorUiFamily
) {
  const speciesId =
    getProjectedTrainerPokemonFieldValue(pokemon, fields, drafts, speciesIdFieldName) ??
    pokemon.speciesId;
  const form =
    getProjectedTrainerPokemonFieldValue(pokemon, fields, drafts, formFieldName) ?? pokemon.form;
  const gender =
    getProjectedTrainerPokemonFieldValue(pokemon, fields, drafts, genderFieldName) ??
    pokemon.gender;
  const level =
    getProjectedTrainerPokemonFieldValue(pokemon, fields, drafts, levelFieldName) ?? pokemon.level;
  const heldItemId =
    getProjectedTrainerPokemonFieldValue(pokemon, fields, drafts, heldItemIdFieldName) ??
    pokemon.heldItemId;
  const heldItemOption = fields
    .find((field) => field.field === heldItemIdFieldName)
    ?.options.find((option) => option.value === heldItemId);
  const referencePokemon =
    pokemonWorkflow?.pokemon.find(
      (candidate) => candidate.speciesId === speciesId && candidate.form === form
    ) ??
    pokemonWorkflow?.pokemon.find(
      (candidate) => candidate.speciesId === speciesId && candidate.form === 0
    ) ??
    null;
  const speciesContext = createDraftSpeciesFormOptionContext(
    fields.find((field) => field.field === speciesIdFieldName),
    drafts[speciesIdFieldName],
    pokemon.species,
    pokemon.speciesId,
    undefined,
    editorFamily,
    undefined,
    pokemon.formOptions
  );
  const usesCurrentIdentity = speciesId === pokemon.speciesId && form === pokemon.form;

  return {
    form,
    gender,
    heldItem:
      heldItemId === 0
        ? null
        : heldItemOption?.label ??
          (heldItemId === pokemon.heldItemId ? pokemon.heldItem : null) ??
          `Item ${heldItemId}`,
    heldItemId,
    level,
    species:
      referencePokemon?.name ??
      (speciesId === pokemon.speciesId ? pokemon.species : speciesContext.species),
    speciesId,
    spriteName:
      referencePokemon?.spriteName ?? (usesCurrentIdentity ? pokemon.spriteName : null)
  };
}

function getProjectedTrainerPokemonStats(
  pokemon: TrainerPokemonRecord,
  fields: TrainerEditableField[],
  drafts: Record<string, string>,
  pokemonWorkflow: PokemonWorkflow | null,
  editorFamily: EditorUiFamily
): ProjectedTrainerPokemonStats | null {
  const speciesId =
    getProjectedTrainerPokemonFieldValue(pokemon, fields, drafts, speciesIdFieldName) ??
    pokemon.speciesId;
  const form =
    getProjectedTrainerPokemonFieldValue(pokemon, fields, drafts, formFieldName) ?? pokemon.form;
  const fallbackBaseStats =
    speciesId === pokemon.speciesId && form === pokemon.form ? pokemon.baseStats ?? null : null;
  const baseStats =
    resolveProjectedTrainerPokemonBaseStats(pokemonWorkflow, speciesId, form) ??
    fallbackBaseStats;

  if (speciesId <= 0 || !baseStats) {
    return null;
  }

  const level = clampInteger(
    getProjectedTrainerPokemonFieldValue(pokemon, fields, drafts, levelFieldName) ??
      pokemon.level,
    1,
    100
  );
  const nature =
    getProjectedTrainerPokemonFieldValue(pokemon, fields, drafts, natureFieldName) ??
    pokemon.nature;
  const effects = getNatureStatEffects(nature, editorFamily);
  const evs = getProjectedTrainerPokemonStatValues(pokemon, fields, drafts, evFieldNames);
  const ivs = getProjectedTrainerPokemonStatValues(pokemon, fields, drafts, ivFieldNames);

  return {
    baseStats,
    stats: {
      hp: calculateProjectedTrainerPokemonStat(
        'hp',
        baseStats.hp,
        normalizeProjectedTrainerEv(evs.hp),
        normalizeProjectedTrainerIv(ivs.hp),
        level,
        effects
      ),
      attack: calculateProjectedTrainerPokemonStat(
        'attack',
        baseStats.attack,
        normalizeProjectedTrainerEv(evs.attack),
        normalizeProjectedTrainerIv(ivs.attack),
        level,
        effects
      ),
      defense: calculateProjectedTrainerPokemonStat(
        'defense',
        baseStats.defense,
        normalizeProjectedTrainerEv(evs.defense),
        normalizeProjectedTrainerIv(ivs.defense),
        level,
        effects
      ),
      specialAttack: calculateProjectedTrainerPokemonStat(
        'specialAttack',
        baseStats.specialAttack,
        normalizeProjectedTrainerEv(evs.specialAttack),
        normalizeProjectedTrainerIv(ivs.specialAttack),
        level,
        effects
      ),
      specialDefense: calculateProjectedTrainerPokemonStat(
        'specialDefense',
        baseStats.specialDefense,
        normalizeProjectedTrainerEv(evs.specialDefense),
        normalizeProjectedTrainerIv(ivs.specialDefense),
        level,
        effects
      ),
      speed: calculateProjectedTrainerPokemonStat(
        'speed',
        baseStats.speed,
        normalizeProjectedTrainerEv(evs.speed),
        normalizeProjectedTrainerIv(ivs.speed),
        level,
        effects
      )
    }
  };
}

function getProjectedTrainerPokemonStatValues(
  pokemon: TrainerPokemonRecord,
  fields: TrainerEditableField[],
  drafts: Record<string, string>,
  fieldNames: typeof evFieldNames | typeof ivFieldNames
): TrainerPokemonRecord['evs'] {
  return {
    hp:
      getProjectedTrainerPokemonFieldValue(pokemon, fields, drafts, fieldNames[0]) ??
      getEditablePokemonFieldValue(pokemon, fieldNames[0]) ??
      0,
    attack:
      getProjectedTrainerPokemonFieldValue(pokemon, fields, drafts, fieldNames[1]) ??
      getEditablePokemonFieldValue(pokemon, fieldNames[1]) ??
      0,
    defense:
      getProjectedTrainerPokemonFieldValue(pokemon, fields, drafts, fieldNames[2]) ??
      getEditablePokemonFieldValue(pokemon, fieldNames[2]) ??
      0,
    specialAttack:
      getProjectedTrainerPokemonFieldValue(pokemon, fields, drafts, fieldNames[3]) ??
      getEditablePokemonFieldValue(pokemon, fieldNames[3]) ??
      0,
    specialDefense:
      getProjectedTrainerPokemonFieldValue(pokemon, fields, drafts, fieldNames[4]) ??
      getEditablePokemonFieldValue(pokemon, fieldNames[4]) ??
      0,
    speed:
      getProjectedTrainerPokemonFieldValue(pokemon, fields, drafts, fieldNames[5]) ??
      getEditablePokemonFieldValue(pokemon, fieldNames[5]) ??
      0
  };
}

function getProjectedTrainerPokemonFieldValue(
  pokemon: TrainerPokemonRecord,
  fields: TrainerEditableField[],
  drafts: Record<string, string>,
  fieldName: string
) {
  const currentValue = getEditablePokemonFieldValue(pokemon, fieldName);
  const field = fields.find((candidate) => candidate.field === fieldName);
  if (!field || currentValue === null) {
    return currentValue;
  }

  const draftValue = drafts[fieldName] ?? currentValue.toString();
  const normalizedDraftValue = draftValue.trim();
  if (normalizedDraftValue.length === 0) {
    return currentValue;
  }

  const parsedValue =
    field.valueKind === 'number'
      ? Number(normalizedDraftValue)
      : parseEditableIntegerDraft(normalizedDraftValue, field.options);

  if (parsedValue === null || !Number.isFinite(parsedValue)) {
    return currentValue;
  }

  const minimumValue = field.minimumValue ?? null;
  const maximumValue = field.maximumValue ?? null;
  if (
    (minimumValue !== null && parsedValue < minimumValue) ||
    (maximumValue !== null && parsedValue > maximumValue)
  ) {
    return currentValue;
  }

  if (
    field.options.length > 0 &&
    !isSpeciesFormField(field.field) &&
    !field.options.some((option) => option.value === parsedValue)
  ) {
    return currentValue;
  }

  return parsedValue;
}

function resolveProjectedTrainerPokemonBaseStats(
  pokemonWorkflow: PokemonWorkflow | null,
  speciesId: number,
  form: number
): TrainerPokemonRecord['baseStats'] | null {
  if (!pokemonWorkflow || speciesId <= 0) {
    return null;
  }

  return (
    pokemonWorkflow.pokemon.find(
      (candidate) => candidate.speciesId === speciesId && candidate.form === form
    )?.baseStats ??
    pokemonWorkflow.pokemon.find(
      (candidate) => candidate.speciesId === speciesId && candidate.form === 0
    )?.baseStats ??
    null
  );
}

function calculateProjectedTrainerPokemonStat(
  statKey: keyof TrainerPokemonRecord['evs'],
  baseStat: number,
  ev: number,
  iv: number,
  level: number,
  effects: NatureStatEffects | null
) {
  if (statKey === 'hp') {
    return baseStat === 1
      ? 1
      : Math.floor(((2 * baseStat + iv + Math.floor(ev / 4)) * level) / 100) + level + 10;
  }

  const neutralStat = Math.floor(((2 * baseStat + iv + Math.floor(ev / 4)) * level) / 100) + 5;
  const natureMultiplier =
    effects?.up === statKey ? 1.1 : effects?.down === statKey ? 0.9 : 1;
  return Math.floor(neutralStat * natureMultiplier);
}

function normalizeProjectedTrainerEv(value: number) {
  return clampInteger(value, 0, maximumPokemonEvValue);
}

function normalizeProjectedTrainerIv(value: number) {
  return clampInteger(value, 0, maximumPokemonIvValue);
}

function getNatureStatAdornment(fieldName: string, effects: NatureStatEffects | null) {
  if (!effects) {
    return null;
  }

  const stat = statFieldKeysByEditableField[
    fieldName as keyof typeof statFieldKeysByEditableField
  ] as NatureStatKey | 'hp' | undefined;
  if (!stat || stat === 'hp') {
    return null;
  }

  if (effects.up === stat) {
    return (
      <span
        className="nature-stat-arrow nature-stat-arrow-up"
        title={`Nature raises ${natureStatLabels[stat]}.`}
      >
        <ArrowUp aria-hidden="true" size={14} />
      </span>
    );
  }

  if (effects.down === stat) {
    return (
      <span
        className="nature-stat-arrow nature-stat-arrow-down"
        title={`Nature lowers ${natureStatLabels[stat]}.`}
      >
        <ArrowDown aria-hidden="true" size={14} />
      </span>
    );
  }

  return null;
}

function getTrainerDataFieldGroup(field: TrainerEditableField) {
  if (
    field.field === trainerClassIdFieldName ||
    field.field === classBallIdFieldName ||
    field.field === battleTypeFieldName ||
    field.field === zaRankFieldName ||
    field.field === zaMegaEvolutionFieldName ||
    field.field === zaLastHandFieldName
  ) {
    return 'Trainer Setup';
  }

  if (field.field === trainerCanTerastallizeFieldName) {
    return 'Terastallization';
  }

  if (trainerItemFieldNames.includes(field.field as (typeof trainerItemFieldNames)[number])) {
    return 'Battle Items';
  }

  if (
    field.field === healFieldName ||
    field.field === moneyFieldName ||
    field.field === giftFieldName
  ) {
    return 'Battle Rewards';
  }

  return 'Trainer Data';
}

function getTrainerPokemonFieldGroup(field: TrainerEditableField) {
  if (
    field.field === speciesIdFieldName ||
    field.field === formFieldName ||
    field.field === levelFieldName ||
    field.field === heldItemIdFieldName
  ) {
    return 'Pokemon';
  }

  if (moveFieldNames.includes(field.field as (typeof moveFieldNames)[number])) {
    return 'Moves';
  }

  if (
    field.field === genderFieldName ||
    field.field === abilityFieldName ||
    field.field === natureFieldName ||
    field.field === dynamaxLevelFieldName ||
    field.field === canGigantamaxFieldName ||
    field.field === shinyFieldName ||
    field.field === trainerTeraTypeFieldName ||
    field.field === canDynamaxFieldName
  ) {
    return 'Traits';
  }

  if (evFieldNames.includes(field.field as (typeof evFieldNames)[number])) {
    return 'Stats - EVs';
  }

  if (ivFieldNames.includes(field.field as (typeof ivFieldNames)[number])) {
    return 'Stats - IVs';
  }

  return 'Pokemon';
}

function getTrainerDraftSummary(
  fields: NumericEditableField[],
  drafts: Record<string, string>,
  getValue: ((field: string) => number | null) | null,
  options: {
    clampIvStats?: boolean;
    enforcePokemonEvLimits?: boolean;
    preservedValues?: Readonly<Record<string, number | null>>;
  } = {}
): { changedFields: TrainerDraftChange[]; dirtyFieldCount: number; invalidFields: TrainerDraftChange[] } {
  const changedFields: TrainerDraftChange[] = [];
  const invalidFields: TrainerDraftChange[] = [];
  let dirtyFieldCount = 0;

  if (!getValue) {
    return { changedFields, dirtyFieldCount, invalidFields };
  }

  const draftContext: DraftStateContext = {
    clampIvStats: options.clampIvStats,
    drafts,
    enforcePokemonEvLimits: options.enforcePokemonEvLimits,
    fields,
    getValue,
    preservedValues: options.preservedValues
  };

  for (const field of fields) {
    const currentValue = getValue(field.field);
    const draftValue = drafts[field.field] ?? '';
    const draftState = getTrainerFieldDraftState(draftValue, currentValue, field, draftContext);

    if (draftState.isChanged || !draftState.isValid) {
      dirtyFieldCount += 1;
    }

    if (!draftState.isValid) {
      invalidFields.push({ field: field.field, label: field.label, value: draftValue });
      continue;
    }

    if (draftState.isChanged && draftState.normalizedValue !== null) {
      changedFields.push({
        field: field.field,
        label: field.label,
        value: draftState.normalizedValue
      });
    }
  }

  return { changedFields, dirtyFieldCount, invalidFields };
}

function getTrainerFieldDraftState(
  draftValue: string,
  currentValue: number | null,
  field: NumericEditableField,
  context?: DraftStateContext
): TrainerDraftState {
  const normalizedValue = draftValue.trim();

  if (currentValue === null && normalizedValue === '') {
    return {
      error: null,
      isChanged: false,
      isValid: true,
      normalizedValue: null
    };
  }

  const currentText = currentValue?.toString() ?? '';

  if (field.valueKind === 'boolean') {
    if (normalizedValue !== '0' && normalizedValue !== '1') {
      return {
        error: 'Choose Yes or No.',
        isChanged: normalizedValue !== currentText,
        isValid: false,
        normalizedValue: null
      };
    }

    return {
      error: null,
      isChanged: normalizedValue !== currentText,
      isValid: true,
      normalizedValue
    };
  }

  if (
    isPokemonInstanceIvPresetField(field.field) &&
    parseEditableIntegerDraft(normalizedValue, [
      ...field.options,
      ivPresetCustomOption
    ]) === ivPresetCustomOptionValue
  ) {
    return {
      error: null,
      isChanged: false,
      isValid: true,
      normalizedValue: null
    };
  }

  if (field.valueKind === 'number') {
    const parsedValue = Number(normalizedValue);
    const minimumValue = field.minimumValue ?? null;
    const maximumValue = field.maximumValue ?? null;

    if (!Number.isFinite(parsedValue)) {
      return {
        error: getIntegerDraftError(normalizedValue),
        isChanged: normalizedValue !== currentText,
        isValid: false,
        normalizedValue: null
      };
    }

    const matchesCurrentValue = currentValue !== null && parsedValue === currentValue;
    const matchesPreservedValue = parsedValue === context?.preservedValues?.[field.field];
    const isAllowedExistingValue = matchesCurrentValue || matchesPreservedValue;

    if (minimumValue !== null && parsedValue < minimumValue && !isAllowedExistingValue) {
      return {
        error: `Minimum value is ${minimumValue}.`,
        isChanged: currentValue === null || parsedValue !== currentValue,
        isValid: false,
        normalizedValue: null
      };
    }

    if (maximumValue !== null && parsedValue > maximumValue && !isAllowedExistingValue) {
      return {
        error: `Maximum value is ${maximumValue}.`,
        isChanged: currentValue === null || parsedValue !== currentValue,
        isValid: false,
        normalizedValue: null
      };
    }

    return {
      error: null,
      isChanged: currentValue === null || Math.abs(parsedValue - currentValue) > Number.EPSILON,
      isValid: true,
      normalizedValue: parsedValue.toString()
    };
  }

  let parsedValue = parseEditableIntegerDraft(normalizedValue, field.options);

  if (parsedValue === null) {
    return {
      error: getIntegerDraftError(normalizedValue),
      isChanged: normalizedValue !== currentText,
      isValid: false,
      normalizedValue: null
    };
  }

  parsedValue = normalizePokemonStatDraftValue(field.field, parsedValue, context);
  const minimumValue = field.minimumValue ?? null;
  const maximumValue = field.maximumValue ?? null;

  const matchesCurrentValue = currentValue !== null && parsedValue === currentValue;
  const matchesPreservedValue = parsedValue === context?.preservedValues?.[field.field];
  const isAllowedExistingValue = matchesCurrentValue || matchesPreservedValue;

  if (minimumValue !== null && parsedValue < minimumValue && !isAllowedExistingValue) {
    return {
      error: `Minimum value is ${minimumValue}.`,
      isChanged: currentValue === null || parsedValue !== currentValue,
      isValid: false,
      normalizedValue: null
    };
  }

  if (maximumValue !== null && parsedValue > maximumValue && !isAllowedExistingValue) {
    return {
      error: `Maximum value is ${maximumValue}.`,
      isChanged: currentValue === null || parsedValue !== currentValue,
      isValid: false,
      normalizedValue: null
    };
  }

  if (
    field.options.length > 0 &&
    !isSpeciesFormField(field.field) &&
    !isAllowedExistingValue &&
    !field.options.some((option) => option.value === parsedValue)
  ) {
    return {
      error: 'Choose one of the available options.',
      isChanged: true,
      isValid: false,
      normalizedValue: null
    };
  }

  return {
    error: null,
    isChanged: currentValue === null || parsedValue !== currentValue,
    isValid: true,
    normalizedValue: parsedValue.toString()
  };
}

function getRentalPokemonDraftSummary(
  rental: RentalPokemonRecord | null,
  fields: NumericEditableField[],
  drafts: Record<string, string>
) {
  const summary = getTrainerDraftSummary(
    fields,
    drafts,
    rental ? (field) => getEditableRentalPokemonFieldValue(rental, field) : null
  );
  if (!rental) {
    return summary;
  }

  const evIssue = getRentalPokemonEvTotalIssue(rental, fields, drafts);
  if (evIssue === null) {
    return summary;
  }

  const invalidFieldNames = new Set(summary.invalidFields.map((field) => field.field));
  const evFieldNamesWithErrors = new Set(evIssue.changedFields);
  const invalidFields = [
    ...summary.invalidFields,
    ...evIssue.changedFields
      .filter((fieldName) => !invalidFieldNames.has(fieldName))
      .map((fieldName) => {
        const field = fields.find((candidate) => candidate.field === fieldName)!;
        return { field: fieldName, label: field.label, value: drafts[fieldName] ?? '' };
      })
  ];

  return {
    ...summary,
    changedFields: summary.changedFields.filter(
      (change) => !evFieldNamesWithErrors.has(change.field)
    ),
    invalidFields
  };
}

function getRentalPokemonFieldDraftState(
  rental: RentalPokemonRecord,
  draftValue: string,
  currentValue: number | null,
  field: NumericEditableField,
  fields: NumericEditableField[],
  drafts: Record<string, string>
) {
  const draftState = getTrainerFieldDraftState(draftValue, currentValue, field, {
    drafts,
    fields,
    getValue: (fieldName) => getEditableRentalPokemonFieldValue(rental, fieldName)
  });
  if (!draftState.isValid) {
    return draftState;
  }

  const evIssue = getRentalPokemonEvTotalIssue(rental, fields, drafts);
  if (
    evIssue !== null &&
    draftState.isChanged &&
    evIssue.changedFields.includes(field.field)
  ) {
    return {
      error: `EV total is ${evIssue.total}. Maximum total is ${maximumPokemonEvTotal}.`,
      isChanged: true,
      isValid: false,
      normalizedValue: null
    };
  }

  return draftState;
}

function getRentalPokemonEvTotalIssue(
  rental: RentalPokemonRecord,
  fields: NumericEditableField[],
  drafts: Record<string, string>
) {
  let total = 0;
  const changedFields: string[] = [];

  for (const fieldName of evFieldNames) {
    const field = fields.find((candidate) => candidate.field === fieldName);
    if (!field) {
      continue;
    }

    const currentValue = getEditableRentalPokemonFieldValue(rental, fieldName);
    const draftValue = drafts[fieldName] ?? currentValue?.toString() ?? '';
    const parsedValue = parseEditableIntegerDraft(draftValue, field.options);
    if (parsedValue === null) {
      return null;
    }

    const draftState = getTrainerFieldDraftState(draftValue, currentValue, field);
    if (!draftState.isValid) {
      return null;
    }

    total += parsedValue;
    if (draftState.isChanged) {
      changedFields.push(fieldName);
    }
  }

  return total > maximumPokemonEvTotal && changedFields.length > 0
    ? { changedFields, total }
    : null;
}

function getStaticEncounterDraftSummary(
  encounter: StaticEncounterRecord | null,
  fields: NumericEditableField[],
  drafts: Record<string, string>,
  allFields: StaticEncounterEditableField[]
) {
  const changedFields: TrainerDraftChange[] = [];
  const invalidFields: TrainerDraftChange[] = [];
  let dirtyFieldCount = 0;

  if (!encounter) {
    return { changedFields, dirtyFieldCount, invalidFields };
  }

  for (const field of fields) {
    if (allFields.find((candidate) => candidate.field === field.field)?.isReadOnly) {
      continue;
    }

    const currentValue = getEditableStaticEncounterFieldValue(encounter, field.field);
    const draftValue = drafts[field.field] ?? '';
    const draftState = getStaticEncounterFieldDraftState(
      encounter,
      draftValue,
      currentValue,
      field,
      allFields,
      drafts
    );

    if (draftState.isChanged || !draftState.isValid) {
      dirtyFieldCount += 1;
    }

    if (!draftState.isValid) {
      invalidFields.push({ field: field.field, label: field.label, value: draftValue });
    } else if (draftState.isChanged && draftState.normalizedValue !== null) {
      changedFields.push({
        field: field.field,
        label: field.label,
        value: draftState.normalizedValue
      });
    }
  }

  return { changedFields, dirtyFieldCount, invalidFields };
}

function getStaticEncounterFieldDraftState(
  encounter: StaticEncounterRecord,
  draftValue: string,
  currentValue: number | null,
  field: NumericEditableField,
  fields: NumericEditableField[],
  drafts: Record<string, string>
): TrainerDraftState {
  const isCustomIvSelected = isPokemonInstanceIvCustomSelected(fields, drafts);
  const draftState = getTrainerFieldDraftState(draftValue, currentValue, field, {
    clampIvStats: encounter.editorFamily !== 'swsh' && isCustomIvSelected,
    drafts,
    fields,
    getValue: (fieldName) => getEditableStaticEncounterFieldValue(encounter, fieldName)
  });

  if (!draftState.isValid) {
    return draftState;
  }

  if (
    encounter.editorFamily === 'swsh' &&
    isCustomIvSelected &&
    isPokemonIvStatField(field.field) &&
    draftState.normalizedValue !== null
  ) {
    const value = Number.parseInt(draftState.normalizedValue, 10);
    const isSupportedSentinel =
      value === -1 || (field.field === ivFieldNames[0] && value === -4);
    if (value < 0 && !isSupportedSentinel) {
      return {
        error:
          field.field === ivFieldNames[0]
            ? 'Use -1 for a random IV, -4 for the 3 perfect IV preset, or 0 through 31.'
            : 'Use -1 for a random IV or 0 through 31.',
        isChanged: draftState.isChanged,
        isValid: false,
        normalizedValue: null
      };
    }
  }

  const ivSentinelIssue = getStaticEncounterIvSentinelIssue(encounter, drafts);
  if (
    ivSentinelIssue !== null &&
    ivSentinelIssue.changedFields.includes(field.field) &&
    draftState.isChanged
  ) {
    return {
      error: 'HP IV -4 requires every other IV to be -1.',
      isChanged: true,
      isValid: false,
      normalizedValue: null
    };
  }

  const evIssue = getStaticEncounterEvTotalIssue(encounter, fields, drafts);
  if (
    evIssue !== null &&
    evIssue.changedFields.includes(field.field) &&
    draftState.isChanged
  ) {
    return {
      error: `EV total is ${evIssue.total}. Maximum total is ${maximumPokemonEvTotal}.`,
      isChanged: true,
      isValid: false,
      normalizedValue: null
    };
  }

  return draftState;
}

function getStaticEncounterIvSentinelIssue(
  encounter: StaticEncounterRecord,
  drafts: Record<string, string>
) {
  if (encounter.editorFamily !== 'swsh') {
    return null;
  }

  const values = Object.fromEntries(
    ivFieldNames.map((fieldName) => {
      const currentValue = getEditableStaticEncounterFieldValue(encounter, fieldName);
      const draftValue = drafts[fieldName];
      const parsedValue =
        draftValue === undefined || draftValue.trim().length === 0
          ? currentValue
          : Number(draftValue.trim());
      return [fieldName, Number.isInteger(parsedValue) ? parsedValue : null];
    })
  ) as Record<(typeof ivFieldNames)[number], number | null>;

  if (values[ivFieldNames[0]] !== -4) {
    return null;
  }

  const hasInvalidNonHpIv = ivFieldNames
    .slice(1)
    .some((fieldName) => values[fieldName] !== -1);
  if (!hasInvalidNonHpIv) {
    return null;
  }

  const changedFields: string[] = ivFieldNames.filter((fieldName) => {
    const currentValue = getEditableStaticEncounterFieldValue(encounter, fieldName);
    return values[fieldName] !== currentValue;
  });

  return changedFields.length > 0 ? { changedFields } : null;
}

function getStaticEncounterEvTotalIssue(
  encounter: StaticEncounterRecord,
  fields: NumericEditableField[],
  drafts: Record<string, string>
) {
  let total = 0;
  const changedFields: string[] = [];

  for (const fieldName of evFieldNames) {
    const field = fields.find((candidate) => candidate.field === fieldName);
    if (!field) {
      continue;
    }

    const currentValue = getEditableStaticEncounterFieldValue(encounter, fieldName);
    const draftValue = drafts[fieldName] ?? currentValue?.toString() ?? '';
    const parsedValue = parseEditableIntegerDraft(draftValue, field.options);
    if (parsedValue === null) {
      return null;
    }

    const draftState = getTrainerFieldDraftState(draftValue, currentValue, field);
    if (!draftState.isValid) {
      return null;
    }

    total += parsedValue;
    if (draftState.isChanged) {
      changedFields.push(fieldName);
    }
  }

  return total > maximumPokemonEvTotal && changedFields.length > 0
    ? { changedFields, total }
    : null;
}

function formatDraftSummary(summary: {
  changedFields: unknown[];
  dirtyFieldCount: number;
  invalidFields: unknown[];
}) {
  if (summary.invalidFields.length > 0) {
    return `${summary.invalidFields.length} field${
      summary.invalidFields.length === 1 ? '' : 's'
    } need valid values`;
  }

  return `${summary.changedFields.length} changed`;
}

