export function formatSpeciesFormLabel(
  species: string,
  form: number,
  speciesId?: number,
  gameFamily?: EditorUiFamily
) {
  if (form < 0) {
    return species;
  }

  const formLabel = resolveSpeciesFormLabel(species, form, speciesId, gameFamily);
  if (form > 0 && formLabel === undefined && speciesHasNonGenericFormSuffix(species)) {
    return species;
  }

  const displaySpecies =
    formLabel === undefined ? species : stripTrailingGenericFormLabel(species, form);
  if (form === 0) {
    return formLabel === undefined || speciesAlreadyIncludesFormLabel(displaySpecies, formLabel)
      ? displaySpecies
      : `${displaySpecies} (${formLabel})`;
  }

  const displayLabel =
    formLabel ??
    `Form ${form}`;

  return speciesAlreadyIncludesFormLabel(displaySpecies, displayLabel)
    ? displaySpecies
    : `${displaySpecies} (${displayLabel})`;
}

function stripTrailingGenericFormLabel(species: string, form: number) {
  if (form < 0) {
    return species;
  }

  return species.replace(new RegExp(`\\s*\\(Form\\s+${form}\\)\\s*$`, 'i'), '').trim();
}

function formatSpeciesFormOptionLabel(form: number, context: SpeciesFormOptionContext) {
  return (
    context.formLabelOverrides?.[form] ??
    resolveSpeciesFormLabel(context.species, form, context.speciesId, context.gameFamily) ??
    (form === 0 ? resolveBaseSpeciesFormLabel(context) ?? 'Base' : `Form ${form}`)
  );
}

function resolveBaseSpeciesFormLabel(context: SpeciesFormOptionContext) {
  const formLabels = getSpeciesFormLabelData(context.gameFamily);
  return (
    (context.speciesId !== undefined
      ? formLabels.baseLabelsBySpeciesId.get(context.speciesId)
      : undefined) ??
    formLabels.baseLabelsBySpeciesName.get(normalizeSpeciesName(context.species))
  );
}

function resolveSpeciesFormLabel(
  species: string,
  form: number,
  speciesId?: number,
  gameFamily?: EditorUiFamily
) {
  const formLabels = getSpeciesFormLabelData(gameFamily);
  return (
    (speciesId !== undefined
      ? formLabels.labelsBySpeciesId.get(`${speciesId}:${form}`)
      : undefined) ??
    formLabels.labelsBySpeciesName.get(`${normalizeSpeciesName(species)}:${form}`)
  );
}

function speciesAlreadyIncludesFormLabel(species: string, formLabel: string) {
  const match = species.trim().match(/\(([^()]*)\)\s*$/);
  return match ? normalizeSpeciesName(match[1] ?? '') === normalizeSpeciesName(formLabel) : false;
}

function speciesHasNonGenericFormSuffix(species: string) {
  const match = species.trim().match(/\(([^()]*)\)\s*$/);
  return match ? !/^form\s+\d+$/i.test(match[1] ?? '') : false;
}

function normalizeSpeciesName(species: string) {
  return species
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9]/g, '')
    .toLocaleLowerCase();
}

function formatStaticEncounterIvs(encounter: StaticEncounterRecord) {
  return [
    `HP ${formatGiftPokemonIvValue(encounter.ivs.hp)}`,
    `Atk ${formatGiftPokemonIvValue(encounter.ivs.attack)}`,
    `Def ${formatGiftPokemonIvValue(encounter.ivs.defense)}`,
    `SpA ${formatGiftPokemonIvValue(encounter.ivs.specialAttack)}`,
    `SpD ${formatGiftPokemonIvValue(encounter.ivs.specialDefense)}`,
    `Spe ${formatGiftPokemonIvValue(encounter.ivs.speed)}`
  ].join(' / ');
}

function formatStaticEncounterStats(stats: StaticEncounterRecord['evs']) {
  return [
    `HP ${stats.hp}`,
    `Atk ${stats.attack}`,
    `Def ${stats.defense}`,
    `SpA ${stats.specialAttack}`,
    `SpD ${stats.specialDefense}`,
    `Spe ${stats.speed}`
  ].join(' / ');
}

function formatStaticEncounterMoves(encounter: StaticEncounterRecord) {
  const moves = encounter.moves
    .filter((move) => move.moveId > 0)
    .map((move) => move.move ?? `Move ${move.moveId}`);

  return moves.length > 0 ? moves.join(' / ') : 'None';
}

function getStaticEncounterDisplayValue(encounter: StaticEncounterRecord, field: string) {
  return encounter.fieldDisplayValues[field] ?? encounter.fieldValues[field] ?? 'None';
}

function formatStaticEncounterScale(encounter: StaticEncounterRecord) {
  const mode = getStaticEncounterDisplayValue(encounter, giftScaleModeFieldName);
  const value = encounter.fieldValues[giftScaleValueFieldName];

  if (!value || value === '0') {
    return mode;
  }

  return `${mode}: ${value}`;
}

function formatRentalPokemonIvs(rental: RentalPokemonRecord) {
  return [
    `HP ${rental.ivs.hp}`,
    `Atk ${rental.ivs.attack}`,
    `Def ${rental.ivs.defense}`,
    `SpA ${rental.ivs.specialAttack}`,
    `SpD ${rental.ivs.specialDefense}`,
    `Spe ${rental.ivs.speed}`
  ].join(' / ');
}

function formatRentalPokemonStats(stats: RentalPokemonRecord['evs']) {
  return [
    `HP ${stats.hp}`,
    `Atk ${stats.attack}`,
    `Def ${stats.defense}`,
    `SpA ${stats.specialAttack}`,
    `SpD ${stats.specialDefense}`,
    `Spe ${stats.speed}`
  ].join(' / ');
}

function formatRentalPokemonMoves(rental: RentalPokemonRecord) {
  const moves = [...rental.moves]
    .sort((left, right) => left.slot - right.slot)
    .filter((move) => move.moveId > 0)
    .map((move) => move.move ?? `Move ${move.moveId}`);

  return moves.length > 0 ? moves.join(' / ') : 'None';
}

function formatDynamaxAdventureIvs(encounter: DynamaxAdventureRecord) {
  const hpValue =
    encounter.guaranteedPerfectIvs > 0
      ? `${encounter.guaranteedPerfectIvs} guaranteed perfect`
      : formatDynamaxAdventureIvValue(encounter.ivs.hp);

  return [
    `HP ${hpValue}`,
    `Atk ${formatDynamaxAdventureIvValue(encounter.ivs.attack)}`,
    `Def ${formatDynamaxAdventureIvValue(encounter.ivs.defense)}`,
    `SpA ${formatDynamaxAdventureIvValue(encounter.ivs.specialAttack)}`,
    `SpD ${formatDynamaxAdventureIvValue(encounter.ivs.specialDefense)}`,
    `Spe ${formatDynamaxAdventureIvValue(encounter.ivs.speed)}`
  ].join(' / ');
}

function formatDynamaxAdventureIvValue(value: number) {
  return value === -1 ? 'Random' : value.toString();
}

function formatDynamaxAdventureMoves(encounter: DynamaxAdventureRecord) {
  const moves = [...encounter.moves]
    .sort((left, right) => left.slot - right.slot)
    .filter((move) => move.moveId > 0)
    .map((move) => move.move ?? `Move ${move.moveId}`);

  return moves.length > 0 ? moves.join(' / ') : 'None';
}

function getFixedRentalPokemonIvPreset(rental: RentalPokemonRecord) {
  const values = [
    rental.ivs.hp,
    rental.ivs.attack,
    rental.ivs.defense,
    rental.ivs.specialAttack,
    rental.ivs.specialDefense,
    rental.ivs.speed
  ];
  const firstValue = values[0] ?? null;

  return firstValue !== null && values.every((value) => value === firstValue)
    ? firstValue
    : null;
}

function formatMovePower(power: number) {
  return power === 0 ? '-' : power.toString();
}

function formatMoveInflictDuration(rawInflictCount: number) {
  const labels: Record<number, string> = {
    0: 'None',
    1: 'Permanent',
    2: 'Turn Count + Switch',
    3: 'Permanent + Switch',
    4: 'Turn Count + No Switch'
  };

  return labels[rawInflictCount] ?? `Raw ${rawInflictCount}`;
}

function formatMoveActiveFlags(move: MoveRecord) {
  const activeFlags = move.flags.filter((flag) => flag.enabled);

  if (activeFlags.length === 0) {
    return '-';
  }

  return activeFlags
    .slice(0, 3)
    .map((flag) => flag.label)
    .join(', ');
}

function formatProjectFileLayer(layer: ChangePlan['writes'][number]['sources'][number]['layer']) {
  return {
    base: 'Base',
    generated: 'Generated',
    layered: 'LayeredFS',
    pending: 'Pending'
  }[layer];
}

function getPathStatusClassName(pathValidation: ProjectPathValidation | undefined) {
  if (!pathValidation) {
    return 'path-status path-status-muted';
  }

  return `path-status path-status-${pathValidation.status}`;
}

async function fetchAvailableUpdate(currentVersion: string): Promise<ReleasePageUpdate | null> {
  const controller = new AbortController();
  let didTimeout = false;
  const timeoutId = window.setTimeout(() => {
    didTimeout = true;
    controller.abort();
  }, githubUpdateCheckTimeoutMs);
  let response: Response;
  let payload: unknown;

  try {
    response = await fetch(githubReleasesApiUrl, {
      headers: {
        Accept: 'application/vnd.github+json'
      },
      signal: controller.signal
    });

    if (!response.ok) {
      throw new Error(`GitHub update check failed (${response.status}).`);
    }

    payload = await response.json();
  } catch (error) {
    if (didTimeout) {
      throw new Error('GitHub update check timed out.', { cause: error });
    }

    throw error;
  } finally {
    window.clearTimeout(timeoutId);
  }

  if (!Array.isArray(payload)) {
    throw new Error('GitHub update response was not a release list.');
  }

  return resolveAvailableUpdate(payload as GithubRelease[], currentVersion);
}

function resolveAvailableUpdate(
  releases: GithubRelease[],
  currentVersionText: string
): ReleasePageUpdate | null {
  const currentVersion = parseVersionTag(currentVersionText);
  if (!currentVersion) {
    return null;
  }

  const updateCandidates = releases
    .map((release) => {
      const version = parseVersionTag(release.tag_name ?? '');
      return version ? { release, version } : null;
    })
    .filter((candidate): candidate is { release: GithubRelease; version: ParsedVersion } => {
      if (!candidate) {
        return false;
      }

      return (
        candidate.release.draft !== true &&
        candidate.release.prerelease !== true &&
        compareVersions(candidate.version, currentVersion) > 0
      );
    })
    .sort((left, right) => compareVersions(right.version, left.version));

  const update = updateCandidates[0];
  if (!update) {
    return null;
  }

  const releaseUrl = update.release.html_url ?? githubLatestReleaseUrl;

  return {
    kind: 'releasePage',
    releaseName: update.release.name?.trim() || update.release.tag_name || 'GitHub release',
    releaseUrl,
    version: formatParsedVersion(update.version)
  };
}

function parseVersionTag(versionText: string): ParsedVersion | null {
  const match = versionText.trim().match(/^v?(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?$/);
  if (!match) {
    return null;
  }

  return {
    major: Number.parseInt(match[1], 10),
    minor: Number.parseInt(match[2], 10),
    patch: Number.parseInt(match[3], 10),
    prerelease: match[4] ?? null
  };
}

function compareVersions(left: ParsedVersion, right: ParsedVersion) {
  const majorDelta = left.major - right.major;
  if (majorDelta !== 0) {
    return majorDelta;
  }

  const minorDelta = left.minor - right.minor;
  if (minorDelta !== 0) {
    return minorDelta;
  }

  const patchDelta = left.patch - right.patch;
  if (patchDelta !== 0) {
    return patchDelta;
  }

  if (left.prerelease === right.prerelease) {
    return 0;
  }

  if (left.prerelease === null) {
    return 1;
  }

  if (right.prerelease === null) {
    return -1;
  }

  return left.prerelease.localeCompare(right.prerelease, undefined, {
    numeric: true,
    sensitivity: 'base'
  });
}

function formatParsedVersion(version: ParsedVersion) {
  return `${version.major}.${version.minor}.${version.patch}${
    version.prerelease ? `-${version.prerelease}` : ''
  }`;
}

function getProjectStateLabel(
  health: ProjectHealth | null,
  projectStatus: 'idle' | 'validating' | 'opening' | 'open',
  activeSection: WorkbenchSection
) {
  if (projectStatus === 'opening') {
    return 'Opening project';
  }

  if (projectStatus === 'validating') {
    return 'Validating paths';
  }

  if (health && readOnlyViewerSectionIds.has(activeSection)) {
    return 'View Only';
  }

  return health ? healthLabels[health.state] : 'No project open';
}

function getRoyalCandyDependencyWarning(
  workflow: RoyalCandyWorkflow | null,
  workflowId: string
): DependencyWarningState | null {
  if (
    !workflow ||
    workflow.summary.availability !== 'available' ||
    workflowId === 'royal-candy-uninstall'
  ) {
    return null;
  }

  const selectedWorkflow = workflow.workflows.find(
    (candidate) => candidate.workflowId === workflowId
  );
  const bagHookCheck = workflow.checks.find(
    (check) =>
      check.workflowId === 'royal-candy-preflight' &&
      check.checkId.endsWith(':bag-hook-installed')
  );
  if (selectedWorkflow?.status !== 'blocked' && bagHookCheck?.status !== 'Fail') {
    return null;
  }

  if (bagHookCheck?.status !== 'Fail') {
    return null;
  }

  return {
    title: 'Bag Hook Required',
    message: 'Royal Candy cannot be staged until Bag Hook V2 is installed.',
    fix:
      'Open Hooks > Bag Hook, stage and save the Bag Hook install, then return to Royal Candy.'
  };
}

function getStartingItemsDependencyWarning(
  workflow: StartingItemsWorkflow | null
): DependencyWarningState | null {
  if (
    !workflow ||
    workflow.summary.availability !== 'available' ||
    workflow.blockerKind !== 'bagHookMissing'
  ) {
    return null;
  }

  return {
    title: 'Bag Hook Required',
    message: 'Starting Items cannot be staged until Bag Hook V2 is installed.',
    fix:
      'Open Hooks > Bag Hook, stage and save the Bag Hook install, then return to Starting Items.'
  };
}

function parseCanonicalPositiveInteger(value: string) {
  const normalizedValue = value.trim();
  if (!/^[1-9]\d*$/.test(normalizedValue)) {
    return null;
  }

  const parsedValue = Number(normalizedValue);
  return Number.isSafeInteger(parsedValue) && parsedValue.toString() === normalizedValue
    ? parsedValue
    : null;
}

function toProjectPaths(draftPaths: ProjectPathDraft, gameTextLanguage: LanguageCode) {
  return {
    baseExeFsPath: normalizeDraftPath(draftPaths.baseExeFsPath),
    baseRomFsPath: normalizeDraftPath(draftPaths.baseRomFsPath),
    gameTextLanguage,
    outputRootPath: normalizeDraftPath(draftPaths.outputRootPath),
    pokemonLegendsZASupportFolderPath: isPokemonLegendsZAGame(draftPaths.selectedGame)
      ? normalizeDraftPath(draftPaths.pokemonLegendsZASupportFolderPath)
      : null,
    saveFilePath: normalizeDraftPath(draftPaths.saveFilePath),
    scarletVioletSupportFolderPath: isScarletVioletGame(draftPaths.selectedGame)
      ? normalizeDraftPath(draftPaths.scarletVioletSupportFolderPath)
      : null,
    selectedGame: draftPaths.selectedGame
  };
}

function resolveOutputRootCreationPath(
  draftPaths: ProjectPathDraft,
  selectedGame: ProjectGame
) {
  const baseRomFsPath = trimTrailingPathSeparators(draftPaths.baseRomFsPath);
  const baseExeFsPath = trimTrailingPathSeparators(draftPaths.baseExeFsPath);

  if (!baseRomFsPath || !baseExeFsPath) {
    return null;
  }

  const romFsParentPath = getParentDirectoryPath(baseRomFsPath);
  const exeFsParentPath = getParentDirectoryPath(baseExeFsPath);

  if (
    !romFsParentPath ||
    !exeFsParentPath ||
    !pathsEqual(romFsParentPath, exeFsParentPath)
  ) {
    return null;
  }

  return joinDirectoryPath(romFsParentPath, gameDefinitions[selectedGame].titleId);
}

function formatByteCount(value: number, formatLocale: string) {
  return `${value.toLocaleString(formatLocale)} bytes`;
}

function formatByteSize(value: number, formatLocale: string) {
  const absoluteValue = Math.max(0, value);
  if (absoluteValue < 1024) {
    return `${absoluteValue.toLocaleString(formatLocale)} B`;
  }

  const units = ['KB', 'MB', 'GB', 'TB'] as const;
  let size = absoluteValue / 1024;
  let unitIndex = 0;
  while (size >= 1024 && unitIndex < units.length - 1) {
    size /= 1024;
    unitIndex += 1;
  }

  const maximumFractionDigits = size >= 10 || unitIndex === 0 ? 0 : 1;
  return `${size.toLocaleString(formatLocale, { maximumFractionDigits })} ${units[unitIndex]}`;
}

function formatCacheSizeLabel(
  value: number | null | undefined,
  formatLocale: string,
  emptyLabel: string,
  unavailableLabel: string
) {
  if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
    return unavailableLabel;
  }

  return value === 0 ? emptyLabel : formatByteSize(value, formatLocale);
}

function formatSvCacheModeLabel(mode: TrinityCacheMode) {
  return svCacheModeOptions.find((option) => option.id === mode)?.label ?? mode;
}

function hasValidScarletVioletSupportFolder(health: ProjectHealth) {
  return health.paths.some(
    (path) => path.role === 'scarletVioletSupportFolder' && path.status === 'valid'
  );
}

function hasValidPokemonLegendsZASupportFolder(health: ProjectHealth) {
  return health.paths.some(
    (path) => path.role === 'pokemonLegendsZASupportFolder' && path.status === 'valid'
  );
}

function hasValidTrinitySupportFolder(
  game: ProjectGame | null | undefined,
  health: ProjectHealth
) {
  return isPokemonLegendsZAGame(game)
    ? hasValidPokemonLegendsZASupportFolder(health)
    : hasValidScarletVioletSupportFolder(health);
}

function getTrinityCacheTitle(game: ProjectGame | null | undefined) {
  if (isSwordShieldGame(game)) return 'Sword/Shield Data Cache';
  return isPokemonLegendsZAGame(game) ? 'Z-A Data Cache' : 'S/V Data Cache';
}

function normalizeDraftPath(path: string) {
  const trimmedPath = path.trim();

  return trimmedPath.length > 0 ? trimmedPath : null;
}

function trimTrailingPathSeparators(path: string) {
  return path.trim().replace(/[\\/]+$/, '');
}

function getParentDirectoryPath(path: string) {
  const separatorIndex = Math.max(path.lastIndexOf('\\'), path.lastIndexOf('/'));

  if (separatorIndex <= 0) {
    return null;
  }

  return path.slice(0, separatorIndex);
}

function joinDirectoryPath(parentPath: string, childName: string) {
  const separator = parentPath.includes('\\') ? '\\' : '/';
  return `${trimTrailingPathSeparators(parentPath)}${separator}${childName}`;
}

function pathsEqual(left: string, right: string) {
  return normalizePathForComparison(left) === normalizePathForComparison(right);
}

function normalizePathForComparison(path: string) {
  return trimTrailingPathSeparators(path).replaceAll('\\', '/').toLowerCase();
}

function createSessionWithPendingEdits(
  session: EditSession | null,
  pendingEdits: EditSession['pendingEdits']
): EditSession | null {
  if (!session || (pendingEdits.length === 0 && !session.authoringBinding)) {
    return null;
  }
  return {
    ...session,
    hasPendingChanges: pendingEdits.length > 0,
    pendingEdits
  };
}

type AdvancedAuthoringDraftProtection = {
  scopeKey: string | null;
  sections: ReadonlySet<RetainedWorkflowSection>;
};

const advancedAuthoringRetainedSections = new Set<RetainedWorkflowSection>([
  'items',
  'moves',
  'pokemon',
  'trainers'
]);

function createAdvancedAuthoringProtectionScopeKey(
  projectId: string | null,
  game: ProjectGame | null,
  activeChangeSetId: string | null
) {
  return projectId && game && activeChangeSetId
    ? JSON.stringify([projectId, game, activeChangeSetId])
    : null;
}

function updateAdvancedAuthoringDraftProtection(
  current: AdvancedAuthoringDraftProtection,
  scopeKey: string | null,
  drafts: AdvancedAuthoringDraftSnapshot | null,
  preserveCurrentScope = false
): AdvancedAuthoringDraftProtection {
  if (preserveCurrentScope && current.scopeKey === scopeKey) {
    return current;
  }
  const sections = drafts
    ? getAdvancedAuthoringDraftSections(drafts)
    : new Set<RetainedWorkflowSection>();
  if (
    current.scopeKey === scopeKey &&
    current.sections.size === sections.size &&
    [...current.sections].every((section) => sections.has(section))
  ) {
    return current;
  }
  return { scopeKey, sections };
}

function getAdvancedAuthoringDraftSections(
  drafts: AdvancedAuthoringDraftSnapshot
) {
  const sections = new Set<RetainedWorkflowSection>();
  const gameFamily = projectGameToFamily(drafts.scope.game);
  for (const entry of drafts.entries) {
    const registration = advancedAuthoringAdapterRegistry.find(
      (candidate) =>
        candidate.domain === entry.field.record.domain &&
        candidate.recordKind === entry.field.record.recordKind.key &&
        candidate.recordKindSchemaVersion ===
          entry.field.record.recordKind.schemaVersion &&
        candidate.games.includes(drafts.scope.game) &&
        entry.field.record.gameFamily === gameFamily
    );
    if (
      registration &&
      advancedAuthoringRetainedSections.has(
        registration.section as RetainedWorkflowSection
      )
    ) {
      sections.add(registration.section as RetainedWorkflowSection);
    }
  }
  return sections;
}

function getPendingEditContentSignature(editSession: EditSession | null) {
  return JSON.stringify((editSession?.pendingEdits ?? []).map((edit) => ({
    domain: edit.domain,
    field: edit.field,
    newValue: edit.newValue,
    owner: edit.owner,
    recordId: edit.recordId,
    summary: edit.summary,
    sources: edit.sources.map((source) => ({
      layer: source.layer,
      relativePath: source.relativePath
    }))
  })));
}

function authoringCaptureTransitionIsValid(
  transition: AuthoringStagedSourceTransition
) {
  const previous = transition.previousSourceBinding;
  const next = transition.nextSourceBinding;
  return (
    previous.version === 1 &&
    next.version === previous.version &&
    previous.projectId === next.projectId &&
    previous.workspaceETag !== next.workspaceETag &&
    /^[A-Fa-f0-9]{64}$/u.test(previous.workspaceETag) &&
    /^[A-Fa-f0-9]{64}$/u.test(next.workspaceETag) &&
    /^[A-Fa-f0-9]{64}$/u.test(previous.workspaceFingerprint) &&
    /^[A-Fa-f0-9]{64}$/u.test(next.workspaceFingerprint) &&
    /^[A-Fa-f0-9]{64}$/u.test(transition.sourceRevisionFingerprint) &&
    previous.outputProfileId === next.outputProfileId &&
    previous.outputMode === next.outputMode &&
    previous.outputRootFingerprint === next.outputRootFingerprint &&
    previous.workspacePersonalStateETag === next.workspacePersonalStateETag &&
    previous.selectedChangeSetIds.length === next.selectedChangeSetIds.length &&
    previous.selectedChangeSetIds.every(
      (changeSetId, index) => changeSetId === next.selectedChangeSetIds[index]
    )
  );
}

function authoringBindingsEqual(
  left: EditSession['authoringBinding'],
  right: EditSession['authoringBinding']
) {
  return (
    left === right ||
    (left != null &&
      right != null &&
      left.version === right.version &&
      left.projectId === right.projectId &&
      left.workspaceETag === right.workspaceETag &&
      left.workspaceFingerprint === right.workspaceFingerprint &&
      left.outputProfileId === right.outputProfileId &&
      left.outputRootFingerprint === right.outputRootFingerprint &&
      left.workspacePersonalStateETag === right.workspacePersonalStateETag &&
      left.outputMode === right.outputMode &&
      left.selectedChangeSetIds.length === right.selectedChangeSetIds.length &&
      left.selectedChangeSetIds.every(
        (changeSetId, index) => changeSetId === right.selectedChangeSetIds[index]
      ))
  );
}

function getEditSessionSignature(editSession: EditSession | null) {
  if (!editSession) {
    return null;
  }

  return JSON.stringify({
    authoringBinding: editSession.authoringBinding
      ? {
          outputProfileId: editSession.authoringBinding.outputProfileId,
          outputMode: editSession.authoringBinding.outputMode,
          outputRootFingerprint: editSession.authoringBinding.outputRootFingerprint,
          projectId: editSession.authoringBinding.projectId,
          selectedChangeSetIds: editSession.authoringBinding.selectedChangeSetIds,
          version: editSession.authoringBinding.version,
          workspaceETag: editSession.authoringBinding.workspaceETag,
          workspaceFingerprint: editSession.authoringBinding.workspaceFingerprint,
          workspacePersonalStateETag:
            editSession.authoringBinding.workspacePersonalStateETag
        }
      : null,
    edits: editSession.pendingEdits.map((edit) => ({
      association: edit.association
        ? {
            changeSetId: edit.association.changeSetId,
            operationId: edit.association.operationId,
            version: edit.association.version
          }
        : null,
      domain: edit.domain,
      field: edit.field,
      newValue: edit.newValue,
      owner: edit.owner,
      recordId: edit.recordId,
      summary: edit.summary,
      sources: edit.sources.map((source) => ({
        layer: source.layer,
        relativePath: source.relativePath
      }))
    })),
    sessionId: editSession.sessionId
  });
}

function delay(milliseconds: number) {
  return new Promise<void>((resolve) => {
    window.setTimeout(resolve, milliseconds);
  });
}

function createSwShPlacementPageWorkflow(
  catalog: SwShPlacementCatalog,
  objects: PlacedObjectRecord[]
): PlacementWorkflow {
  return {
    categories: catalog.categories,
    diagnostics: catalog.diagnostics,
    editableFields: catalog.editableFields,
    objects,
    stats: catalog.stats,
    summary: catalog.summary
  };
}

function isSwordShieldGame(
  game: ProjectGame | null | undefined
): game is Extract<NonNullable<ProjectGame>, 'sword' | 'shield'> {
  return game === 'sword' || game === 'shield';
}

function isProjectCacheGame(
  game: ProjectGame | null | undefined
): game is NonNullable<ProjectGame> {
  return isSwordShieldGame(game) || isTrinityCacheGame(game);
}

function hasValidProjectCacheSource(game: ProjectGame, health: ProjectHealth) {
  return isSwordShieldGame(game)
    ? health.canOpenReadOnlyWorkflows
    : hasValidTrinitySupportFolder(game, health);
}

function getProjectCacheStatusForGame(
  bridge: ProjectBridge,
  game: ProjectGame,
  paths: ReturnType<typeof toProjectPaths> | null
) {
  if (isSwordShieldGame(game)) return bridge.getSwShCacheStatus({ paths });
  if (isPokemonLegendsZAGame(game)) return bridge.getZaCacheStatus({ paths });
  return bridge.getSvCacheStatus({ paths });
}

function updateProjectCacheSettingsForGame(
  bridge: ProjectBridge,
  game: ProjectGame,
  mode: TrinityCacheMode,
  maxCacheSizeBytes: number,
  paths: ReturnType<typeof toProjectPaths> | null
) {
  const request = { maxCacheSizeBytes, mode, paths };
  if (isSwordShieldGame(game)) return bridge.updateSwShCacheSettings(request);
  if (isPokemonLegendsZAGame(game)) return bridge.updateZaCacheSettings(request);
  return bridge.updateSvCacheSettings(request);
}

function clearProjectCacheForGame(
  bridge: ProjectBridge,
  game: ProjectGame,
  activePaths: ReturnType<typeof toProjectPaths> | null
) {
  if (isSwordShieldGame(game)) return bridge.clearSwShCache({ activePaths });
  if (isPokemonLegendsZAGame(game)) return bridge.clearZaCache({ activePaths });
  return bridge.clearSvCache({ activePaths });
}

function warmupProjectCacheStepForGame(
  bridge: ProjectBridge,
  game: ProjectGame,
  paths: ReturnType<typeof toProjectPaths>,
  stepIndex: number
) {
  const request = { paths, stepIndex };
  if (isSwordShieldGame(game)) return bridge.warmupSwShCacheStep(request);
  if (isPokemonLegendsZAGame(game)) return bridge.warmupZaCacheStep(request);
  return bridge.warmupSvCacheStep(request);
}

type UiDiagnosticFallback =
  | {
      domain: 'bridge';
      message?: string;
    }
  | {
      code: KmErrorCode;
      domain: 'desktop';
      message: string;
    };

function toOperationDiagnostics(
  error: unknown,
  fallback: UiDiagnosticFallback
): ApiDiagnostic[] {
  if (isStaleProjectScopeError(error)) {
    return [];
  }

  if (error instanceof ProjectBridgeError) {
    return toProjectBridgeDiagnostics(error, fallback.message);
  }

  if (error instanceof DesktopServiceError) {
    return toDesktopErrorDiagnostics(
      error,
      fallback.message ?? 'Desktop operation failed.',
      error.code
    );
  }

  return fallback.domain === 'desktop'
    ? toDesktopErrorDiagnostics(error, fallback.message, fallback.code)
    : toProjectBridgeDiagnostics(error, fallback.message);
}

function toBridgeDiagnostics(error: unknown): ApiDiagnostic[] {
  return toOperationDiagnostics(error, {
    domain: 'bridge',
    message: 'Project bridge request failed.'
  });
}

function isStaleSwShPlacementCatalogError(error: unknown) {
  if (!(error instanceof ProjectBridgeError)) {
    return false;
  }

  if (error.apiError.code === swshPlacementErrorCodes.catalogStale) {
    return true;
  }

  const message = error.apiError.message.toLocaleLowerCase();
  return (
    message.includes('placement source data changed after this catalog was opened') ||
    message.includes('selected placement object is no longer present') ||
    message.includes('placement catalog revision is required')
  );
}

function toDesktopDiagnostics(
  error: unknown,
  fallbackMessage: string,
  fallbackCode: KmErrorCode = desktopErrorCodes.unexpected
): ApiDiagnostic[] {
  return toOperationDiagnostics(error, {
    code: fallbackCode,
    domain: 'desktop',
    message: fallbackMessage
  });
}

function isSupportFileSearchCancellation(error: unknown) {
  if (
    typeof error === 'object' &&
    error !== null &&
    'code' in error &&
    error.code === desktopErrorCodes.supportFileSearchCanceled
  ) {
    return true;
  }

  const message =
    error instanceof Error ? error.message : typeof error === 'string' ? error : null;
  return message === 'Support file search was canceled.';
}

function getErrorMessage(error: unknown) {
  if (error instanceof Error) {
    return sanitizeReportableErrorText(error.message).slice(0, 1024);
  }
  return 'The private workspace operation failed.';
}

function resolveSemanticInspectorLayer(
  snapshots: readonly {
    layer: { kind: QueryableLayer | 'comparedMod' };
  }[]
): QueryableLayer {
  const layers = new Set(snapshots.map((snapshot) => snapshot.layer.kind));
  if (layers.has('pending')) {
    return 'pending';
  }
  if (layers.has('layered')) {
    return 'layered';
  }
  return 'base';
}

function toProjectPathDraft(paths: {
  baseExeFsPath?: string | null;
  baseRomFsPath?: string | null;
  outputRootPath?: string | null;
  pokemonLegendsZASupportFolderPath?: string | null;
  saveFilePath?: string | null;
  scarletVioletSupportFolderPath?: string | null;
  selectedGame?: ProjectGame | null;
}): ProjectPathDraft {
  return {
    baseExeFsPath: paths.baseExeFsPath ?? '',
    baseRomFsPath: paths.baseRomFsPath ?? '',
    outputRootPath: paths.outputRootPath ?? '',
    pokemonLegendsZASupportFolderPath:
      paths.pokemonLegendsZASupportFolderPath ?? '',
    saveFilePath: paths.saveFilePath ?? '',
    scarletVioletSupportFolderPath:
      paths.scarletVioletSupportFolderPath ?? '',
    selectedGame: paths.selectedGame ?? null
  };
}

function hasConfiguredProjectPath(paths: ProjectPathDraft) {
  return [
    paths.baseExeFsPath,
    paths.baseRomFsPath,
    paths.outputRootPath,
    paths.pokemonLegendsZASupportFolderPath,
    paths.saveFilePath,
    paths.scarletVioletSupportFolderPath
  ].some((path) => path.length > 0);
}

function projectPathValuesEqual(left: ProjectPathDraft, right: ProjectPathDraft) {
  return (
    left.baseExeFsPath === right.baseExeFsPath &&
    left.baseRomFsPath === right.baseRomFsPath &&
    left.outputRootPath === right.outputRootPath &&
    left.pokemonLegendsZASupportFolderPath ===
      right.pokemonLegendsZASupportFolderPath &&
    left.saveFilePath === right.saveFilePath &&
    left.scarletVioletSupportFolderPath === right.scarletVioletSupportFolderPath
  );
}

function toScopedWorkspaceLocation(location: WorkbenchLocation): WorkspaceScopedLocation {
  if (!location.game) {
    throw new Error('A saved Workbench location requires a game.');
  }
  return {
    ...(location.changeSetId ? { changeSetId: location.changeSetId } : {}),
    ...(location.entity ? { entity: location.entity } : {}),
    game: location.game,
    ...(location.inspectorTab ? { inspectorTab: location.inspectorTab } : {}),
    section: location.section,
    ...(location.subcontext ? { subcontext: { ...location.subcontext } } : {}),
    version: 1
  };
}

function fromScopedWorkspaceLocation(
  location: WorkspaceScopedLocation,
  projectId: string | null
) {
  if (!projectId) return null;
  try {
    return createWorkbenchLocation({
      ...(location.changeSetId ? { changeSetId: location.changeSetId } : {}),
      ...(location.entity ? { entity: location.entity } : {}),
      game: location.game,
      ...(location.inspectorTab ? { inspectorTab: location.inspectorTab } : {}),
      projectId,
      section: location.section,
      ...(location.subcontext ? { subcontext: location.subcontext } : {})
    });
  } catch {
    return null;
  }
}

function withoutScopedLocationInspector(
  location: WorkspaceScopedLocation
): WorkspaceScopedLocation {
  const canonicalLocation = { ...location };
  delete canonicalLocation.inspectorTab;
  return canonicalLocation;
}

function scopedWorkspaceLocationsEqual(
  left: WorkspaceScopedLocation,
  right: WorkspaceScopedLocation
) {
  return workspaceScopedLocationKey(left) === workspaceScopedLocationKey(right);
}

function createWorkspaceTargetViewModel(
  location: WorkbenchLocation,
  translate: (key: string) => string
): WorkspaceTargetViewModel {
  return {
    description: location.entity
      ? translate(getWorkbenchSectionLabelKey(location.section))
      : null,
    id: serializeWorkbenchLocation(location),
    label: location.entity
      ? location.entity.recordId
      : translate(getWorkbenchSectionLabelKey(location.section)),
    labelIsRawData: Boolean(location.entity),
    location
  };
}

function canonicalJsonStringify(value: unknown): string {
  if (value === null || typeof value !== 'object') {
    const serializedValue = JSON.stringify(value);
    if (serializedValue === undefined) {
      throw new Error('A saved view payload must contain JSON values only.');
    }
    return serializedValue;
  }
  if (Array.isArray(value)) {
    return `[${value.map((entry) => canonicalJsonStringify(entry)).join(',')}]`;
  }
  const record = value as Record<string, unknown>;
  return `{${Object.keys(record)
    .sort()
    .map((key) => `${JSON.stringify(key)}:${canonicalJsonStringify(record[key])}`)
    .join(',')}}`;
}

async function createDeterministicSavedViewId(
  adapterId: string,
  adapterSchemaVersion: number,
  location: WorkspaceScopedLocation,
  canonicalPayload: string
) {
  const identity = [
    adapterId,
    String(adapterSchemaVersion),
    workspaceScopedLocationKey(location),
    canonicalPayload
  ].join('\u001f');
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(identity));
  const fingerprint = Array.from(
    new Uint8Array(digest),
    (byte) => byte.toString(16).padStart(2, '0')
  ).join('');
  return `search-view:${adapterId}:${adapterSchemaVersion}:${fingerprint}`;
}

function createWorkspaceEntryId() {
  return typeof crypto.randomUUID === 'function'
    ? crypto.randomUUID()
    : `entry-${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
}

function createSafeWorkspaceShortcutRegistry(
  overrides: readonly { commandId: string; shortcut: string }[]
) {
  try {
    return createWorkspaceShortcutRegistry(
      Object.fromEntries(overrides.map((entry) => [entry.commandId, entry.shortcut]))
    );
  } catch {
    return createWorkspaceShortcutRegistry();
  }
}

const recipeExportDomains = new Set([
  'workflow.items',
  'workflow.pokemon',
  'workflow.moves'
]);

function getRecipeExportEligibility(changeSet: NamedChangeSet): {
  recipeExportDomain: string | null;
  recipeExportEligibility: 'eligible' | 'empty' | 'binding' | 'payload' | 'mixedDomain';
  recipeExportFieldKeys: readonly string[];
  recipeExportTargetKeys: readonly string[];
} {
  if (changeSet.operations.length === 0) {
    return {
      recipeExportDomain: null,
      recipeExportEligibility: 'empty',
      recipeExportFieldKeys: [],
      recipeExportTargetKeys: []
    };
  }
  if (changeSet.operations.some((operation) => operation.sourceBindingKind !== 'reviewedPlan')) {
    return {
      recipeExportDomain: null,
      recipeExportEligibility: 'binding',
      recipeExportFieldKeys: [],
      recipeExportTargetKeys: []
    };
  }
  const domains = new Set(changeSet.operations.map((operation) => operation.pendingEdit.domain));
  if (
    domains.size !== 1 ||
    [...domains].some((domain) => !recipeExportDomains.has(domain))
  ) {
    return {
      recipeExportDomain: null,
      recipeExportEligibility: 'mixedDomain',
      recipeExportFieldKeys: [],
      recipeExportTargetKeys: []
    };
  }
  const targetKeys: string[] = [];
  if (changeSet.operations.some((operation) => {
    const { domain, field, newValue, recordId } = operation.pendingEdit;
    const numericRecordId = recordId === undefined || recordId === null
      ? Number.NaN
      : Number(recordId);
    const numericValue = newValue === undefined || newValue === null
      ? Number.NaN
      : Number(newValue);
    const minimumRecordId = domain === 'workflow.moves' ? 0 : 1;
    if (
      field == null ||
      !/^[a-z][A-Za-z0-9]*$/u.test(field) ||
      field.length > 128 ||
      recordId == null ||
      !Number.isInteger(numericRecordId) ||
      numericRecordId < minimumRecordId ||
      numericRecordId > 2_147_483_647 ||
      String(numericRecordId) !== recordId ||
      newValue == null ||
      !Number.isInteger(numericValue) ||
      numericValue < -2_147_483_648 ||
      numericValue > 2_147_483_647 ||
      String(numericValue) !== newValue
    ) return true;
    targetKeys.push(JSON.stringify([domain, recordId, field]));
    return false;
  }) || new Set(targetKeys).size !== targetKeys.length) {
    return {
      recipeExportDomain: null,
      recipeExportEligibility: 'payload',
      recipeExportFieldKeys: [],
      recipeExportTargetKeys: []
    };
  }
  return {
    recipeExportDomain: [...domains][0] ?? null,
    recipeExportEligibility: 'eligible',
    recipeExportFieldKeys: [...new Set(changeSet.operations.map(
      (operation) => operation.pendingEdit.field!
    ))].sort(),
    recipeExportTargetKeys: targetKeys.sort()
  };
}

function toErrorMessage(error: unknown, fallback: UiDiagnosticFallback) {
  const diagnostics = toOperationDiagnostics(error, fallback);
  if (diagnostics.length === 0) {
    return fallback.message ?? 'The operation was canceled.';
  }

  return diagnostics
    .map((diagnostic) => {
      if (!diagnostic.code || diagnostic.message.includes(`Error code: ${diagnostic.code}`)) {
        return diagnostic.message;
      }

      return `${diagnostic.message}\nError code: ${diagnostic.code}`;
    })
    .join('\n\n');
}
